1	// Saved-card / off-session charging primitives for subscription renewals.
2	//
3	// WHY THIS FILE EXISTS
4	// Until now a renewal could only debit the wallet (`worker/billing.ts` ->
5	// `debitWallet`). A customer with a perfectly good card on file was suspended the
6	// moment their wallet emptied, because `User.stripePaymentMethodId` was never
7	// written and never read. Everything needed to charge a card lives here; the
8	// worker owns the *policy* (when to retry, when to suspend), this module owns the
9	// *mechanics* (attach a card, charge it, credit the wallet for what it paid).
10	//
11	// THE MONEY MODEL — identical to checkout, deliberately
12	// Checkout applies wallet credit first and puts only the remainder on the card
13	// (`lib/wallet-split.ts`). Renewals now do the same: the card is charged the
14	// remainder, that exact amount is CREDITED to the wallet, and the existing
15	// CAS-guarded renewal transaction debits the FULL renewal from the wallet. So the
16	// wallet is always the thing that pays the bill and the card is always just a way
17	// to fund the wallet — one money path, already proven, and a partial failure can
18	// never half-apply a renewal.
19	//
20	// Plain server module (NOT "use server"): imported by the worker, by server
21	// actions and by server components. `lib/stripe.ts` is not modified by this file.
22	
23	import type Stripe from "stripe";
24	import { db } from "./db";
25	import { stripe, stripeConfigured, stripePublishableKey, EMBEDDED_UI_MODE, EMBEDDED_REQUEST_OPTS, type EmbeddedCheckout } from "./stripe";
26	import { STRIPE_MIN_CENTS } from "./wallet-split";
27	import { invoiceCreateData } from "./invoices";
28	// NOTE: no pricing imports here on purpose. `vpsTerm`, `vpsTermPriceCents` and
29	// `extraDiskCentsAt` were still imported after `renewalCharge` moved out to
30	// ./renewal-charge, leaving this file holding every ingredient of the renewal
31	// formula and nothing that used them — an invitation to write the second copy that
32	// lib/renewal-quote.ts documents two incidents about. The one formula lives in
33	// ./renewal-charge and is re-exported below.
34	
35	/* ------------------------------------------------------------------ *
36	 * Small shared helpers
37	 * ------------------------------------------------------------------ */
38	
39	function appBase(): string {
40	  return process.env.APP_URL ?? "http://localhost:3000";
41	}
42	
43	/** Audit actions used to decide whether an unclaimed Stripe card may be adopted. */
44	export const CARD_SETUP_STARTED = "card.setup_started";
45	export const CARD_REMOVED = "card.removed";
46	
47	/** How long a "I clicked Add card" intent stays good for the adoption backstop. */
48	const SETUP_INTENT_TTL_DAYS = 7;
49	
50	export type CardDisplay = {
51	  brand: string | null;
52	  last4: string | null;
53	  expMonth: number | null;
54	  expYear: number | null;
55	};
56	
57	/** "Visa ···· 4242, expires 04/28" — one formatter for UI, email and audit text. */
58	export function cardDisplayLabel(card: CardDisplay): string | null {
59	  if (!card.last4) return null;
60	  const brand = brandLabel(card.brand);
61	  const expiry =
62	    card.expMonth && card.expYear
63	      ? `, expires ${String(card.expMonth).padStart(2, "0")}/${String(card.expYear).slice(-2)}`
64	      : "";
65	  return `${brand} ···· ${card.last4}${expiry}`;
66	}
67	
68	/** Stripe brand ids are lowercase slugs ("visa", "amex", "unionpay"). */
69	export function brandLabel(brand: string | null | undefined): string {
70	  const map: Record<string, string> = {
71	    visa: "Visa",
72	    mastercard: "Mastercard",
73	    amex: "American Express",
74	    discover: "Discover",
75	    diners: "Diners Club",
76	    jcb: "JCB",
77	    unionpay: "UnionPay",
78	    cartes_bancaires: "Cartes Bancaires",
79	    eftpos_au: "Eftpos",
80	    link: "Link",
81	  };
82	  if (!brand) return "Card";
83	  return map[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
84	}
85	
86	/**
87	 * A card is valid THROUGH the last day of its expiry month, so it stops working
88	 * at the first instant of the following month. Getting this off by a month would
89	 * either nag customers a month early or warn them after the renewal already failed.
90	 */
91	export function cardExpiresAt(expMonth: number, expYear: number): Date {
92	  return new Date(Date.UTC(expYear, expMonth, 1));
93	}
94	
95	/* ------------------------------------------------------------------ *
96	 * Renewal pricing — ONE formula, two callers
97	 * ------------------------------------------------------------------ */
98	
99	/**
100	 * What a renewal costs. Lives here (rather than being copied a third time)
101	 * because BOTH the worker sweep and the customer-facing "settle the balance"
102	 * link have to quote the same number — `renewNow` and the sweep already carry
103	 * the comment "the two renewal paths must never disagree", and a self-service
104	 * pay link that quotes a different total than the sweep charges is exactly how
105	 * that goes wrong.
106	 *
107	 * Pure: prices are passed in so the worker can read the admin settings once per
108	 * sweep instead of once per server.
109	 */
110	// `renewalCharge` and its types now live in ./renewal-charge — a pure module with
111	// no SDK imports, so client components can price a renewal without pulling the
112	// Stripe SDK and nodemailer into the browser bundle. Re-exported here so every
113	// existing server-side importer keeps working unchanged.
114	export { renewalCharge, type RenewalCharge, type PricedServer } from "./renewal-charge";
115	
116	/* ------------------------------------------------------------------ *
117	 * Stripe customer + saving a card
118	 * ------------------------------------------------------------------ */
119	
120	export type CardUser = {
121	  id: string;
122	  email: string;
123	  name?: string | null;
124	  stripeCustomerId: string | null;
125	  stripePaymentMethodId: string | null;
126	};
127	
128	/** True when this account can actually be charged off-session right now. */
129	export function hasChargeableCard(user: {
130	  stripeCustomerId: string | null;
131	  stripePaymentMethodId: string | null;
132	}): boolean {
133	  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
134	}
135	
136	/**
137	 * Get-or-create the Stripe customer for an account and remember its id.
138	 *
139	 * `User.stripeCustomerId` has no UNIQUE constraint (the schema is frozen), so two
140	 * concurrent "Add card" clicks could otherwise mint two Stripe customers for one
141	 * person and strand the card on whichever one lost. The idempotency key — derived
142	 * only from our own user id — is what stops that: Stripe replays the first
143	 * customer instead of creating a second.
144	 */
145	export async function ensureStripeCustomer(user: CardUser): Promise<string> {
146	  if (user.stripeCustomerId) return user.stripeCustomerId;
147	  const fresh = await db.user.findUnique({
148	    where: { id: user.id },
149	    select: { stripeCustomerId: true },
150	  });
151	  if (fresh?.stripeCustomerId) return fresh.stripeCustomerId;
152	
153	  const customer = await stripe().customers.create(
154	    {
155	      email: user.email,
156	      name: user.name || undefined,
157	      metadata: { nxeonUserId: user.id },
158	    },
159	    { idempotencyKey: `nxeon_customer_${user.id}` },
160	  );
161	  await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customer.id } });
162	  return customer.id;
163	}
164	
165	/**
166	 * Hosted Checkout session in `mode: "setup"` — how a customer saves a card.
167	 *
168	 * Checkout rather than Stripe Elements because there is no Elements/Stripe.js
169	 * integration anywhere in this codebase and no publishable key plumbed to the
170	 * browser; a redirect to Stripe's own page reuses the exact flow that already
171	 * takes money for deploys, upgrades and top-ups.
172	 *
173	 * `usage: "off_session"` is load-bearing: it records a mandate that covers the
174	 * unattended renewal charges we make later. Without it many issuers (and every
175	 * SCA-regulated card) reject the first off-session charge outright, which would
176	 * turn "saved card" into "card that is declined once a month".
177	 */
178	export async function createCardSetupSession(
179	  user: CardUser,
180	  returnPath = "/dashboard/billing",
181	): Promise<EmbeddedCheckout | null> {
182	  if (!stripeConfigured()) return null;
183	  const customerId = await ensureStripeCustomer(user);
184	  const base = appBase();
185	  const session = await stripe().checkout.sessions.create({
186	    mode: "setup",
187	    // EMBEDDED, not hosted — the card form renders in a modal ON our page
188	    // (StripeCheckoutModal); no redirect to a Stripe-branded page. On completion Stripe
189	    // navigates to `return_url` (returnPath?card_setup=<id>) where the existing
190	    // finalize-on-return logic runs UNCHANGED. `cancel_url` is invalid with embedded;
191	    // the modal's close button is the cancel (nothing finalises → a safe no-op).
192	    // embedded_page + the pinned API version (EMBEDDED_REQUEST_OPTS below) — see the
193	    // EMBEDDED_UI_MODE doc in lib/stripe.ts for why both are required.
194	    ui_mode: EMBEDDED_UI_MODE,
195	    customer: customerId,
196	    payment_method_types: ["card"],
197	    setup_intent_data: { metadata: { nxeonUserId: user.id } },
198	    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
199	    // returnPath may already carry a query (e.g. the Deploy hub's ?product=hosting),
200	    // so append card_setup with the correct separator.
201	    return_url: `${base}${returnPath}${returnPath.includes("?") ? "&" : "?"}card_setup={CHECKOUT_SESSION_ID}`,
202	  }, EMBEDDED_REQUEST_OPTS);
203	  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
204	}
205	
206	/** Mirror the display fields + payment method for a card onto the account. */
207	async function persistCard(userId: string, customerId: string, pm: Stripe.PaymentMethod) {
208	  await db.user.update({
209	    where: { id: userId },
210	    data: {
211	      stripeCustomerId: customerId,
212	      stripePaymentMethodId: pm.id,
213	      cardBrand: pm.card?.brand ?? null,
214	      cardLast4: pm.card?.last4 ?? null,
215	      cardExpMonth: pm.card?.exp_month ?? null,
216	      cardExpYear: pm.card?.exp_year ?? null,
217	      // A brand-new card gets a fresh expiry-warning budget, otherwise a customer
218	      // who replaces an expiring card would never be warned about the new one.
219	      cardExpiryNotifiedAt: null,
220	    },
221	  });
222	}
223	
224	export type SavedCard = { brand: string | null; last4: string | null; expMonth: number | null; expYear: number | null };
225	
226	/**
227	 * Finalise a completed setup Checkout session: read the payment method off it,
228	 * make it the customer's default and mirror it onto the account.
229	 *
230	 * Verifies `metadata.nxeonUserId` against the caller. The session id travels in a
231	 * URL the customer can edit, so without that check a customer could paste someone
232	 * else's session id and attach their card to their own account.
233	 */
234	export async function saveCardFromSetupSession(
235	  sessionId: string,
236	  userId: string,
237	): Promise<{ card?: SavedCard; error?: string }> {
238	  if (!stripeConfigured()) return { error: "Card payments are not configured." };
239	  let session: Stripe.Checkout.Session;
240	  try {
241	    session = await stripe().checkout.sessions.retrieve(sessionId, { expand: ["setup_intent"] });
242	  } catch {
243	    return { error: "We couldn't read that card setup. Try adding the card again." };
244	  }
245	  if (session.mode !== "setup" || session.metadata?.nxeonUserId !== userId) {
246	    return { error: "That card setup doesn't belong to this account." };
247	  }
248	  if (session.status !== "complete") {
249	    return { error: "The card wasn't saved — the setup wasn't completed." };
250	  }
251	  const setupIntent = session.setup_intent as Stripe.SetupIntent | string | null;
252	  const pmRef =
253	    typeof setupIntent === "string" ? null : (setupIntent?.payment_method ?? null);
254	  const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
255	  const customerId =
256	    typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
257	  if (!pmId || !customerId) return { error: "The card wasn't saved — no payment method came back." };
258	
259	  const pm = await stripe().paymentMethods.retrieve(pmId);
260	  // Checkout already attached the method to the customer; making it the default
261	  // means the adoption backstop below and anything Stripe-side pick the same card.
262	  await stripe()
263	    .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
264	    .catch(() => {
265	      /* non-fatal: our own stripePaymentMethodId is the source of truth for charging */
266	    });
267	  await persistCard(userId, customerId, pm);
268	  return {
269	    card: {
270	      brand: pm.card?.brand ?? null,
271	      last4: pm.card?.last4 ?? null,
272	      expMonth: pm.card?.exp_month ?? null,
273	      expYear: pm.card?.exp_year ?? null,
274	    },
275	  };
276	}
277	
278	/**
279	 * Backstop for the closed-tab case.
280	 *
281	 * Checkout attaches the card to the Stripe customer BEFORE our `success_url` ever
282	 * runs. A customer who completes the Stripe page and then closes the tab has a
283	 * perfectly good card on file at Stripe and none on file here — and would be
284	 * dunned and suspended for it. This is the same class of bug as the Stripe
285	 * fulfilment incident: a browser redirect must never be the only trigger.
286	 *
287	 * Adoption is deliberately narrow. It requires a `card.setup_started` audit row
288	 * newer than any `card.removed` row and no older than a week, so a card the
289	 * customer explicitly REMOVED can never be silently resurrected and charged.
290	 */
291	export async function adoptUnclaimedCards(now = new Date()): Promise<number> {
292	  if (!stripeConfigured()) return 0;
293	  const since = new Date(now.getTime() - SETUP_INTENT_TTL_DAYS * 86400_000);
294	  const starts = await db.auditLog.findMany({
295	    where: { action: CARD_SETUP_STARTED, createdAt: { gt: since } },
296	    orderBy: { createdAt: "desc" },
297	    take: 200,
298	  });
299	  const userIds = [...new Set(starts.map((a) => a.userId).filter((v): v is string => !!v))];
300	  if (userIds.length === 0) return 0;
301	
302	  let adopted = 0;
303	  for (const userId of userIds) {
304	    const user = await db.user.findUnique({ where: { id: userId } });
305	    if (!user?.stripeCustomerId || user.stripePaymentMethodId) continue;
306	
307	    const startedAt = starts.find((a) => a.userId === userId)!.createdAt;
308	    const removed = await db.auditLog.findFirst({
309	      where: { userId, action: CARD_REMOVED },
310	      orderBy: { createdAt: "desc" },
311	    });
312	    if (removed && removed.createdAt > startedAt) continue; // removal is the later intent
313	
314	    try {
315	      const list = await stripe().paymentMethods.list({
316	        customer: user.stripeCustomerId,
317	        type: "card",
318	        limit: 5,
319	      });
320	      const pm = list.data[0]; // newest first
321	      if (!pm) continue;
322	      await persistCard(userId, user.stripeCustomerId, pm);
323	      await db.auditLog.create({
324	        data: {
325	          userId,
326	          action: "card.adopted",
327	          detail: `${cardDisplayLabel({
328	            brand: pm.card?.brand ?? null,
329	            last4: pm.card?.last4 ?? null,
330	            expMonth: pm.card?.exp_month ?? null,
331	            expYear: pm.card?.exp_year ?? null,
332	          })} (saved at Stripe but never confirmed in the browser)`,
333	        },
334	      });
335	      adopted++;
336	    } catch (e) {
337	      console.error(`[cards] could not adopt card for ${userId}`, e);
338	    }
339	  }
340	  return adopted;
341	}
342	
343	/**
344	 * Remove the saved card: detach at Stripe FIRST, and only clear our columns once
345	 * Stripe agrees the method is gone. Clearing locally while the method is still
346	 * attached would let `adoptUnclaimedCards` re-adopt it and charge a card the
347	 * customer had removed. A method that is already missing counts as removed.
348	 */
349	export async function detachSavedCard(userId: string): Promise<{ ok?: true; error?: string }> {
350	  const user = await db.user.findUnique({ where: { id: userId } });
351	  if (!user) return { error: "Account not found." };
352	  if (!user.stripePaymentMethodId) {
353	    await clearCardColumns(userId);
354	    return { ok: true };
355	  }
356	  if (stripeConfigured()) {
357	    try {
358	      await stripe().paymentMethods.detach(user.stripePaymentMethodId);
359	    } catch (e) {
360	      const err = asStripeError(e);
361	      if (err?.code !== "resource_missing") {
362	        console.error("[cards] detach failed", e);
363	        return { error: "We couldn't remove the card just now. Please try again in a moment." };
364	      }
365	    }
366	  }
367	  await clearCardColumns(userId);
368	  return { ok: true };
369	}
370	
371	async function clearCardColumns(userId: string) {
372	  await db.user.update({
373	    where: { id: userId },
374	    data: {
375	      stripePaymentMethodId: null,
376	      cardBrand: null,
377	      cardLast4: null,
378	      cardExpMonth: null,
379	      cardExpYear: null,
380	      cardExpiryNotifiedAt: null,
381	    },
382	  });
383	}
384	
385	/**
386	 * A customer who saves a card mid-dunning has been told (by
387	 * `emails.paymentFailed`) that we'll "charge it straight away". Bringing the
388	 * scheduled retry forward is what makes that copy true — the next sweep picks it
389	 * up instead of waiting for the day-3 or day-5 slot. The failure COUNT is left
390	 * alone: the money is still owed.
391	 */
392	export async function retryDunningNow(userId: string): Promise<number> {
393	  const res = await db.server.updateMany({
394	    where: { userId, dunningStage: { gt: 0 } },
395	    data: { dunningNextAt: new Date() },
396	  });
397	  return res.count;
398	}
399	
400	/* ------------------------------------------------------------------ *
401	 * Off-session charging
402	 * ------------------------------------------------------------------ */
403	
404	type StripeErrorLike = {
405	  type?: string;
406	  rawType?: string;
407	  code?: string;
408	  decline_code?: string;
409	  message?: string;
410	  payment_intent?: { id?: string; status?: string };
411	};
412	
413	function asStripeError(e: unknown): StripeErrorLike | null {
414	  if (!e || typeof e !== "object") return null;
415	  const err = e as StripeErrorLike;
416	  return err.rawType || err.type?.startsWith("Stripe") ? err : null;
417	}
418	
419	export type OffSessionResult =
420	  /** Money captured. `amountCents` is what Stripe actually took, not what we asked for. */
421	  | { ok: true; paymentIntentId: string; amountCents: number; replayed: boolean }
422	  /** 3-D Secure or equivalent: the customer must approve it with their bank. */
423	  | { ok: false; kind: "requires_action"; paymentIntentId: string | null; message: string }
424	  /** The issuer said no. A real dunning event. */
425	  | { ok: false; kind: "declined"; message: string; code?: string }
426	  /** Our side or Stripe's side wobbled. NOT the customer's fault — never dun for it. */
427	  | { ok: false; kind: "transient"; message: string }
428	  /** Nothing to charge with (no card, Stripe off, amount under Stripe's floor). */
429	  | { ok: false; kind: "unavailable"; message: string };
430	
431	/**
432	 * Stable per-purpose marker written into PaymentIntent metadata.
433	 *
434	 * This is a SECOND idempotency guard that does not expire. Stripe's own
435	 * idempotency keys are only honoured for 24 hours, and our dunning schedule spans
436	 * six days, so the key alone cannot answer "have we already been paid for this
437	 * period?". Before charging we look for a live PaymentIntent carrying this marker
438	 * and reuse it — so a crash between "Stripe captured the money" and "we recorded
439	 * the payment intent id" can never turn into a second charge.
440	 */
441	export function renewalChargeMarker(serverId: string, periodStart: Date): string {
442	  return `renew:${serverId}:${periodStart.toISOString()}`;
443	}
444	
445	/** Marker for an automatic wallet top-up: at most one per account per day. */
446	export function autoRechargeMarker(userId: string, now: Date): string {
447	  return `autorecharge:${userId}:${now.toISOString().slice(0, 10)}`;
448	}
449	
450	/** Look for a charge we may already have made for this exact purpose. */
451	async function findChargeByMarker(
452	  customerId: string,
453	  marker: string,
454	): Promise<Stripe.PaymentIntent | null> {
455	  // Stripe's maximum page size, and it is the number that matters rather than a
456	  // comfortable-looking one. This lookup is the guard that DOES NOT EXPIRE, and it
457	  // is the only one covering the gap between a day-3 retry and the day-5 retry —
458	  // Stripe honours an idempotency key for just 24 hours while the dunning ladder
459	  // runs six days. It was 25 on the reasoning that "renewals are monthly", which
460	  // holds per server and not per CUSTOMER: this list is scoped to the customer, so
461	  // an account with thirty servers renewing in one sweep pushes the marker off the
462	  // first page and the permanent guard silently stops guarding — at which point a
463	  // crash between "Stripe captured" and "we recorded it" charges the card twice for
464	  // one period.
465	  const list = await stripe().paymentIntents.list({ customer: customerId, limit: 100 });
466	  const mine = list.data.filter((pi) => pi.metadata?.nxeonChargeKey === marker);
467	  return (
468	    mine.find((pi) => pi.status === "succeeded") ??
469	    mine.find((pi) => pi.status === "requires_action") ??
470	    mine.find((pi) => pi.status === "processing") ??
471	    null
472	  );
473	}
474	
475	/**
476	 * Charge the saved card off-session (no customer present).
477	 *
478	 * Two independent idempotency guards, because this moves real money on a timer
479	 * that retries:
480	 *  1. `marker` — pre-flight lookup of a live PaymentIntent for this exact purpose.
481	 *     Survives forever, catches the crash-after-capture window.
482	 *  2. `idempotencyKey` — Stripe replays the identical request instead of charging
483	 *     twice when two sweeps overlap. Only good for 24h, hence guard 1.
484	 */
485	export async function chargeSavedCardOffSession(opts: {
486	  user: CardUser;
487	  amountCents: number;
488	  description: string;
489	  marker: string;
490	  idempotencyKey: string;
491	  metadata?: Record<string, string>;
492	}): Promise<OffSessionResult> {
493	  const { user, amountCents, description, marker, idempotencyKey } = opts;
494	  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
495	  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
496	    return { ok: false, kind: "unavailable", message: "No saved card" };
497	  }
498	  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
499	  // the belt-and-braces check so a future caller can't send a rejectable amount.
500	  if (amountCents < STRIPE_MIN_CENTS) {
501	    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
502	  }
503	
504	  // Guard 1: did we already charge for this purpose?
505	  try {
506	    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
507	    if (existing?.status === "succeeded") {
508	      return {
509	        ok: true,
510	        paymentIntentId: existing.id,
511	        amountCents: existing.amount_received || existing.amount,
512	        replayed: true,
513	      };
514	    }
515	    if (existing?.status === "requires_action") {
516	      // A 3-D Secure wall does not move: retrying the SAME card off-session hits it
517	      // again, so reuse the existing intent (and its link) rather than piling up a
518	      // new challenge every retry. A DIFFERENT card is a different story — if the
519	      // customer has since saved one, cancel the stale challenge and really try it,
520	      // otherwise saving a new card would silently change nothing.
521	      const pendingPm =
522	        typeof existing.payment_method === "string"
523	          ? existing.payment_method
524	          : (existing.payment_method?.id ?? null);
525	      if (pendingPm === user.stripePaymentMethodId) {
526	        return {
527	          ok: false,
528	          kind: "requires_action",
529	          paymentIntentId: existing.id,
530	          message: "Awaiting bank confirmation",
531	        };
532	      }
533	      await cancelIfUnconfirmed(existing.id);
534	    }
535	    if (existing?.status === "processing") {
536	      return { ok: false, kind: "transient", message: "A charge for this period is still settling" };
537	    }
538	  } catch (e) {
539	    // A failed lookup must not become a blind second charge.
540	    console.error("[cards] pre-flight charge lookup failed", e);
541	    return { ok: false, kind: "transient", message: "Could not verify existing charges" };
542	  }
543	
544	  try {
545	    const pi = await stripe().paymentIntents.create(
546	      {
547	        amount: amountCents,
548	        currency: "usd",
549	        customer: user.stripeCustomerId,
550	        payment_method: user.stripePaymentMethodId,
551	        confirm: true,
552	        off_session: true,
553	        // No browser exists here, so a redirect-based next_action could never be
554	        // satisfied — and asking for one is what makes Stripe demand a return_url.
555	        automatic_payment_methods: { enabled: true, allow_redirects: "never" },
556	        description,
557	        metadata: { ...(opts.metadata ?? {}), nxeonUserId: user.id, nxeonChargeKey: marker },
558	      },
559	      { idempotencyKey },
560	    );
561	    if (pi.status === "succeeded") {
562	      return { ok: true, paymentIntentId: pi.id, amountCents: pi.amount_received || pi.amount, replayed: false };
563	    }
564	    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
565	      return { ok: false, kind: "requires_action", paymentIntentId: pi.id, message: "Bank confirmation required" };
566	    }
567	    if (pi.status === "processing") {
568	      return { ok: false, kind: "transient", message: "Payment is still processing" };
569	    }
570	    return { ok: false, kind: "declined", message: `Payment could not be completed (${pi.status})` };
571	  } catch (e) {
572	    return classifyChargeError(e);
573	  }
574	}
