576	/**
577	 * Split a charge failure into the three cases that deserve different treatment:
578	 * the bank wants the customer to confirm, the bank said no, or nothing about the
579	 * customer went wrong at all.
580	 *
581	 * The default is `transient` on purpose. A misclassified transient error costs us
582	 * a delayed renewal; a misclassified decline costs a paid-up customer their
583	 * server. Unknown always resolves to the direction that cannot suspend anyone.
584	 */
585	function classifyChargeError(e: unknown): OffSessionResult {
586	  const err = asStripeError(e);
587	  const message = String(err?.message ?? (e as Error)?.message ?? e).slice(0, 300);
588	  if (!err) return { ok: false, kind: "transient", message };
589	
590	  // 3-D Secure surfaces as a card error with this code, with the PI attached.
591	  if (err.code === "authentication_required" || err.payment_intent?.status === "requires_action") {
592	    return {
593	      ok: false,
594	      kind: "requires_action",
595	      paymentIntentId: err.payment_intent?.id ?? null,
596	      message,
597	    };
598	  }
599	  if (err.rawType === "card_error") {
600	    return { ok: false, kind: "declined", message, code: err.decline_code ?? err.code };
601	  }
602	  // The saved method vanished at Stripe (detached elsewhere, customer deleted).
603	  // Not a decline — there is nothing to retry until a new card is saved.
604	  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
605	    return { ok: false, kind: "unavailable", message };
606	  }
607	  return { ok: false, kind: "transient", message };
608	}
