684	/**
685	 * Hosted Checkout link for an outstanding renewal balance.
686	 *
687	 * Carries ONLY `nxeonUserId` in metadata, which makes the shared, already-proven
688	 * fulfilment path treat it as a wallet top-up: the money lands as wallet credit
689	 * and the next sweep renews from the wallet. That is why this is also the answer
690	 * to 3-D Secure — Checkout collects the bank challenge on Stripe's own page, so we
691	 * never need Stripe.js in the browser or a second confirmation code path.
692	 *
693	 * The quoted amount is the remainder the wallet cannot cover AT THIS MOMENT. If
694	 * the customer spends their credit before paying, the next sweep simply recomputes
695	 * the split and asks the card for the new remainder — it self-heals rather than
696	 * over- or under-charging.
697	 */
698	export async function createOutstandingCheckout(opts: {
699	  user: { id: string; email: string; stripeCustomerId: string | null };
700	  amountCents: number;
701	  hostname: string;
702	  serverId: string;
703	}): Promise<string | null> {
704	  if (!stripeConfigured()) return null;
705	  // Guard the INPUT, not the floored amount. `if (amount <= 0)` sat AFTER the
706	  // `Math.max(STRIPE_MIN_CENTS, …)` below and was therefore dead code: an
707	  // `amountCents` of 0 — a caller whose wallet already covers the renewal, or one
708	  // whose split came back with no card leg — was floored up to 50c and became a
709	  // real hosted-checkout page asking a customer who owes nothing for fifty cents.
710	  // Nothing due means no link, not a minimum charge.
711	  const due = Math.round(opts.amountCents);
712	  if (!Number.isFinite(due) || due <= 0) return null;
713	  // Stripe rejects a charge under its floor, and the surplus is honest here in a
714	  // way it would not be elsewhere: this session credits the WALLET, so a 30c
715	  // balance settled with the 50c minimum leaves the customer 20c of their own
716	  // credit, not 20c of our revenue. The page states the amount it charges.
717	  const amount = Math.max(STRIPE_MIN_CENTS, due);
718	  const base = appBase();
719	  try {
720	    const session = await stripe().checkout.sessions.create({
721	      mode: "payment",
722	      ...(opts.user.stripeCustomerId
723	        ? { customer: opts.user.stripeCustomerId }
724	        : { customer_email: opts.user.email }),
725	      line_items: [
726	        {
727	          price_data: {
728	            currency: "usd",
729	            product_data: {
730	              name: `Nxeon renewal — ${opts.hostname}`,
731	              description:
732	                "Settles the outstanding renewal balance. Added to your Nxeon wallet and applied to this renewal automatically.",
733	            },
734	            unit_amount: amount,
735	          },
736	          quantity: 1,
737	        },
738	      ],
739	      metadata: { nxeonUserId: opts.user.id },
740	      success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
741	      cancel_url: `${base}/dashboard/servers/${opts.serverId}`,
742	    });
743	    return session.url;
744	  } catch (e) {
745	    console.error("[cards] could not create outstanding-balance checkout", e);
746	    return null;
747	  }
748	}
