60	/**
61	 * Tell the customer their money is safe and someone knows. Called only on a path
62	 * where the card HAS cleared and fulfilment did not happen, so silence is the one
63	 * outcome that is never acceptable.
64	 */
65	async function notifyStalled(userId: string) {
