78	/**
79	 * Report a completed order as an ad-conversion, exactly once, on the WINNING fulfil
80	 * call (this only runs where `fulfilled === true`, so no double count under the
81	 * redirect/webhook race). Fires the server-side Meta Conversions API event — best
82	 * effort, inert unless the pixel id + CAPI token are set, and it never throws into
83	 * fulfilment — then returns the redirect tagged with the SAME event_id and the real
84	 * charged amount (`session.amount_total`, what Stripe actually took), so the browser
85	 * pixel (`PurchaseTracker`) can fire and Meta dedupes the pair into ONE conversion.
86	 * READ-ONLY on money: it reports the amount, it never changes a charge.
87	 */
88	async function reportPurchase(
89	  redirect: string,
90	  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
91	  email?: string,
92	  userId?: string,
93	  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
94	  prod?: string,
95	): Promise<string> {
96	  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
97	  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
98	  const currency = (session.currency ?? "usd").toUpperCase();
99	  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
100	  // Wrapped so the webhook path (no browser request scope) simply sends without them.
101	  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
102	  try {
103	    const [ck, h] = await Promise.all([cookies(), headers()]);
104	    fbc = ck.get("_fbc")?.value || undefined;
105	    fbp = ck.get("_fbp")?.value || undefined;
106	    userAgent = h.get("user-agent") ?? undefined;
107	    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
108	  } catch {
109	    /* no request scope (webhook) — send without cookie/UA signals */
110	  }
111	  const { eventId } = await sendMetaConversion({
112	    eventName: "Purchase",
113	    email,
114	    value,
115	    currency,
116	    sourceUrl: redirect,
117	    fbc,
118	    fbp,
119	    userAgent,
120	    clientIp,
121	    externalId: userId,
122	  });
123	  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
124	  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
125	}
