127	/**
128	 * Credit the wallet and fulfil whatever the session was for, exactly once.
129	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
130	 *
131	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
132	 * defect found on 2026-07-27: this function used to ask three helpers for the
133	 * session, each of which swallowed every error into `null`, so a transient Stripe
134	 * failure was indistinguishable from "no purchase metadata" and fell through to
135	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
136	 * card charged with no server, no FulfilledSession row and no notification — and
137	 * because the webhook returns 200 either way, Stripe never retried it. A throw
138	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
139	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
140	 */
141	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
142	  // ONE retrieve, one view of the session, shared by the credit and the routing.
143	  const session = await retrieveCheckoutSession(sessionId);
144	  const purpose = classifyCheckoutSession(session);
145	
146	  // Nothing was paid (an abandoned session id, or one replayed before capture).
147	  // Never claim fulfilment for money that has not arrived.
148	  if (purpose.kind === "unpaid") {
149	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
150	  }
151	
152	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
153	  // transaction). We deliberately IGNORE its return value now — it reports who
154	  // won the credit race, which is not the same question as "has this been
155	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
156	  // race: the money has not reached the wallet, so nothing below may spend it.
157	  await creditCheckoutSession(session);
158	
159	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
160	  // it, so claim the session and record the failure exactly like a failed order:
161	  // reconcilable, and the customer is told. What it must NEVER become is a silent
162	  // wallet top-up, which is precisely what the old `null` fall-through produced.
163	  if (purpose.kind === "unreadable") {
164	    if (await claim(sessionId, "unreadable")) {
165	      await settle(sessionId, "FAILED", purpose.detail);
166	      if (purpose.userId) await notifyStalled(purpose.userId);
167	    }
168	    return {
169	      redirect: `${base}/dashboard/billing?paid=1`,
170	      fulfilled: false,
171	      kind: "none",
172	      error: purpose.detail,
173	    };
174	  }
175	
176	  const order = purpose.kind === "order" ? purpose : null;
177	  if (order) {
178	    if (!(await claim(sessionId, "order"))) {
179	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
180	    }
181	    try {
182	      const user = await db.user.findUnique({ where: { id: order.userId } });
183	      if (!user) throw new Error("user not found for paid order");
184	      // Settle the price stamped on the session BEFORE the card was charged — never
185	      // a fresh quote taken now. The customer has already paid the card leg of that
186	      // exact total; re-pricing here and taking the difference out of the wallet is
187	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
188	      // the resize and disk-expand branches below, which have always passed the
189	      // amount through metadata for this reason.
190	      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
191	      // per-IP cap can't be enforced here — the per-account unique still holds, and
192	      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
193	      // the card was charged, so the double-claim race is closed regardless. Fulfilment
194	      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
195	      // fresh claim. `campaign` rides in via metadata so attribution survives the card
196	      // round-trip even in the webhook (no cookies).
197	      const serverId = await placeOrder(user, order.intent, order.sold, {
198	        ipHash: null,
199	        campaign: order.campaign,
200	        promoReservationToken: order.promoReservationToken,
201	        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
202	        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
203	        // token rather than contending for a fresh claim — no double-claim, no over-charge.
204	        couponReservationToken: order.couponReservationToken,
205	      });
206	      await settle(sessionId, "DONE", serverId);
207	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "vps");
208	      return { redirect, fulfilled: true, kind: "order" };
209	    } catch (e) {
210	      // Payment is captured and the funds are in the wallet — record the failure
211	      // so it is reconcilable rather than invisible, and tell the customer.
212	      const msg = String((e as Error)?.message ?? e);
213	      await settle(sessionId, "FAILED", msg);
214	      await notifyStalled(order.userId);
215	      // Deploy-funnel: the card CLEARED but the order couldn't be placed — the one
216	      // payment-tail failure only visible server-side (the browser has left the
