231	 *                                                 saved card for the remainder
232	 *  - card declined                             -> dunning (retry days 1/3/5 + email)
233	 *  - retries exhausted, or no card past grace  -> queue SUSPEND with unpaid note
234	 * Free servers (isFree) are never touched.
235	 */
236	export async function billingSweep() {
237	  const now = new Date();
238	  const cfg = await dunningConfig();
239	  const prices = {
240	    ipMonthlyCents: await dedicatedIpMonthlyCents(), // admin setting; 0 = included
241	    // Per-GB/month price for extra ROOT DISK. Read once per sweep; every server that
242	    // bought extra storage renews at plan + (extraDiskGB x this) x months, so the
243	    // upsell keeps billing every cycle rather than being a one-off charge.
244	    extraDiskPerGbCents: await extraDiskPerGbCents(),
245	    // Monthly price of the Plus backup-retention tier. A server on Plus renews at
246	    // plan + this x months, folded into totalCents by renewalCharge exactly like
247	    // the extra-disk line, so the retention upsell keeps billing every cycle.
248	    backupPlusCents: await backupPlusMonthlyCents(),
249	    // The admin ANNUAL discount. A 12-month server renews at this rate — the same
250	    // one it was ordered and displayed at — so an annual subscription renews for
251	    // another year at the SAME annual price. Ignored for every other term.
252	    annualDiscountPct: await annualDiscountPct(),
253	  };
254	  // Seller country + global fallback rate, read ONCE per sweep. The per-server VAT
255	  // rate is resolved (purely) from each owner's billing country against these, so the
256	  // renewal charge, the card leg and the invoice all carry the same tax the customer
257	  // is shown elsewhere (Finding 1).
258	  const taxParams = { sellerCountry: await sellerCountry(), fallbackPercent: await taxRate() };
259	  const taxCtxFor = (u: { billingCountry?: string | null; vatId?: string | null }): TaxContext =>
260	    resolveCountryTaxRate({
261	      country: u.billingCountry ?? null,
262	      vatId: u.vatId ?? null,
263	      sellerCountry: taxParams.sellerCountry,
264	      fallbackPercent: taxParams.fallbackPercent,
265	    });
266	
267	  // Claim any card that was saved at Stripe but never confirmed in the browser,
268	  // BEFORE the renewal queries read card state — otherwise a customer who closed
269	  // the tab on Stripe's page gets dunned for a card we simply failed to record.
270	  try {
271	    const adopted = await adoptUnclaimedCards(now);
272	    if (adopted > 0) console.log(`[billing] adopted ${adopted} unconfirmed saved card(s)`);
273	  } catch (e) {
274	    console.error("[billing] card adoption error", e);
275	  }
276	
277	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
278	  const soon = new Date(now.getTime() + 3 * 86400_000);
279	  const upcoming = await db.server.findMany({
280	    where: {
281	      isFree: false,
282	      expiresAt: { gt: now, lt: soon },
283	      status: { in: ["RUNNING", "STOPPED"] },
284	    },
285	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
286	  });
287	  for (const server of upcoming) {
288	    // Tax-inclusive so the "renewal is $X" warning matches what the sweep will take.
289	    const warnCents = renewalCharge(server, { ...prices, taxRatePercent: taxCtxFor(server.user).ratePercent }).totalCents;
290	    // A customer with a card on file needs no warning and no top-up: the renewal
291	    // applies their wallet credit and auto-charges the card for the remainder.
292	    // Telling them to "top up to avoid suspension" would raise an alarm about a
293	    // suspension that is not going to happen.
294	    if (server.autoRenew && (server.user.balanceCents >= warnCents || hasChargeableCard(server.user))) {
295	      continue;
296	    }
297	    const already = await db.notification.findFirst({
298	      where: {
299	        userId: server.userId,
300	        title: { contains: server.hostname },
301	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
302	        AND: { title: { contains: "renews soon" } },
303	      },
304	    });
305	    if (!already) {
306	      await db.notification.create({
307	        data: {
308	          userId: server.userId,
309	          title: `${server.hostname} renews soon — action needed`,
310	          body: server.autoRenew
311	            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
312	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
313	          href: `/dashboard/servers/${server.id}`,
314	        },
315	      });
316	    }
317	  }
318	  const due = await dueServers(now);
319	
320	  for (const server of due) {
321	    // One unhappy server must never abort the queue behind it. Every money write
322	    // below is individually guarded (CAS on expiresAt, UNIQUE on the payment intent
323	    // id, Stripe idempotency key), so continuing past a failure can only ever cost a
324	    // delayed renewal — never a duplicate charge. Without this, a single row with a
325	    // wedged Stripe customer would leave every later customer unrenewed AND
326	    // eventually suspended, for a fault that was entirely ours.
327	    try {
328	      await renewDueServer(server, { now, cfg, prices, taxParams });
329	    } catch (e) {
330	      console.error(`[billing] renewal pass failed for ${server.hostname}`, e);
331	    }
332	  }
333	
334	  await terminateOverdue(now, cfg);
335	  await reapAbandonedSuspended(now, cfg);
336	
337	  // Card housekeeping: nudge before a saved card expires, and honour the customer's
338	  // own automatic top-up preference. Both are isolated so a Stripe or SMTP problem
339	  // can never take the renewal sweep down with it.
340	  try {
341	    await cardExpirySweep(now);
342	  } catch (e) {
343	    console.error("[billing] card-expiry sweep error", e);
344	  }
345	  try {
346	    await autoRechargeSweep(now);
347	  } catch (e) {
348	    console.error("[billing] auto-recharge sweep error", e);
349	  }
350	
351	  await domainAutoRenewSweep(now);
352	
353	  // Poll in-flight inbound transfers on the same cadence as domain renewals —
354	  // domain upkeep all lives on one timer.
355	  try {
356	    await domainTransferInSweep(now);
357	  } catch (e) {
358	    console.error("[billing] domain transfer-in sweep error", e);
359	  }
360	}
