362	/**
363	 * One expired server: renew it from wallet + card, or move it along the dunning
364	 * sequence, or suspend it once every promised attempt is spent.
365	 */
366	async function renewDueServer(
367	  server: DueServer,
368	  ctx: {
369	    now: Date;
370	    cfg: DunningConfig;
371	    prices: { ipMonthlyCents: number; extraDiskPerGbCents: number; backupPlusCents: number; annualDiscountPct: number };
372	    taxParams: { sellerCountry: string; fallbackPercent: number };
373	  },
374	) {
375	  const { now, cfg, taxParams } = ctx;
376	  // Resolve the owner's VAT/GST from their billing country (Finding 1) and fold it
377	  // into the renewal price so the wallet debit, any card leg and the invoice all
378	  // agree. Default rate 0 (no country on file) leaves this identical to before.
379	  const taxCtx = resolveCountryTaxRate({
380	    country: server.user.billingCountry ?? null,
381	    vatId: server.user.vatId ?? null,
382	    sellerCountry: taxParams.sellerCountry,
383	    fallbackPercent: taxParams.fallbackPercent,
384	  });
385	  const prices = { ...ctx.prices, taxRatePercent: taxCtx.ratePercent };
386	  const charge = renewalCharge(server, prices);
387	  const renewCents = charge.totalCents;
388	  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
389	  const newExpiry = addMonths(base, charge.months);
390	
391	  await clearStaleDunning(server);
392	
393	  let renewed = false;
394	  if (server.autoRenew) {
395	    // `server.user.balanceCents` came from a snapshot taken before this loop and
396	    // is stale as soon as the first renewal in this pass debits a wallet, so the
397	    // SPLIT is computed from a fresh read. It is still never a gate: `debitWallet`
398	    // re-checks funds atomically and the compare-and-swap on `expiresAt` stops a
399	    // concurrent renewNow()/second pass charging the same period twice.
400	    const fresh = await db.user.findUnique({
401	      where: { id: server.userId },
402	      select: { balanceCents: true },
403	    });
404	    const split = walletSplit({
405	      dueCents: renewCents,
406	      balanceCents: fresh?.balanceCents ?? 0,
407	      useWallet: true,
408	    });
409	    const cardInPlay = hasChargeableCard(server.user);
410	
411	    if (split.cardCents === 0) {
412	      // Wallet covers the whole renewal — no card involved, no Stripe call.
413	      const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry: taxCtx.country });
414	      renewed = outcome !== "insufficient";
415	      if (outcome === "renewed") {
416	        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
417	      }
418	    } else if (cardInPlay) {
419	      // Only attempt on the scheduled day. Without this gate a 10-minute sweep
420	      // would burn all three retries — and send all three emails — within half an
421	      // hour of the first decline.
422	      //
423	      // A scheduled time, once set, ALWAYS wins over the attempt counter, which buys
424	      // two things. `retryDunningNow` (fired when a customer saves a new card
425	      // mid-dunning) gets a real attempt even at the exhausted stage — refusing there
426	      // would suspend a customer whose brand-new card we never once tried. And the
427	      // exhausted stage's schedule points at the suspension day itself, so every
428	      // server gets one final, silent try at the card in the same pass that pauses it.
429	      const dueForRetry = server.dunningNextAt
430	        ? now >= server.dunningNextAt
431	        : server.dunningStage < DUNNING_EXHAUSTED;
432	      if (dueForRetry) {
433	        renewed = await attemptCardRenewal({
434	          server,
435	          charge,
436	          cardCents: split.cardCents,
437	          newExpiry,
438	          now,
439	          cfg,
440	          taxCountry: taxCtx.country,
441	        });
442	      }
443	    } else {
444	      console.log(
445	        `[billing] ${server.hostname} short by ${fmtUsd(split.cardCents)} and no card on file — grace/suspend applies`,
446	      );
447	    }
448	  }
449	
450	  if (renewed) {
451	    // nothing further this pass
452	  } else {
453	    const suspendAt = suspendDueAt(server, hasChargeableCard(server.user), cfg);
454	    if (suspendAt && now >= suspendAt) {
455	      await suspendUnpaid(server, cfg);
456	    }
457	  }
458	}
