460	/**
461	 * Drop dunning state that belongs to a period we are no longer collecting for.
462	 *
463	 * `renewNow` (lib/actions.ts) advances `expiresAt` without touching the dunning
464	 * columns, so a customer who paid by hand halfway through a sequence carries a
465	 * stale `dunningStage` into the NEXT period — and the first decline of that fresh
466	 * period would arrive as "payment retry 2 declined, 1 attempt remaining", on a
467	 * compressed schedule, for a period they had never failed once.
468	 *
469	 * Every schedule this file writes lands at or after the expiry it was computed
470	 * from, so a `dunningNextAt` that predates the CURRENT `expiresAt` can only have
471	 * been written for an older, already-settled period.
472	 */
473	async function clearStaleDunning(server: DueServer): Promise<void> {
474	  if (server.dunningStage === 0 && !server.dunningNextAt && !server.dunningPayUrl) return;
475	  const belongsToThisPeriod = server.dunningNextAt && server.dunningNextAt >= server.expiresAt!;
476	  if (belongsToThisPeriod) return;
477	
478	  await db.server.update({
479	    where: { id: server.id },
480	    data: { dunningStage: 0, dunningNextAt: null, dunningPayUrl: null },
481	  });
482	  // Keep the in-memory row honest: the rest of this pass reads these fields to
483	  // decide whether to charge, which email to send and when to suspend.
484	  server.dunningStage = 0;
485	  server.dunningNextAt = null;
486	  server.dunningPayUrl = null;
487	}
