489	/* ------------------------------------------------------------------ *
490	 * Renewal commit (wallet) + card auto-charge
491	 * ------------------------------------------------------------------ */
492	
493	/**
494	 * Advance the term and take the money from the wallet, atomically.
495	 *
496	 * This is the ONLY place a VPS renewal is granted, whether the wallet was funded
497	 * by a top-up, a referral credit or the saved card moments ago. One money path
498	 * means a partial failure can never half-apply a renewal: either the period
499	 * advances AND the wallet is debited AND the invoice exists, or none of it happened.
500	 *
501	 * The compare-and-swap on `expiresAt` is the idempotency guard. A retried sweep, a
502	 * second worker or a concurrent `renewNow` all read the same snapshot expiry; only
503	 * the first `updateMany` to match it writes, and every loser rolls back its debit
504	 * and its invoice with the transaction. Zero rows matched = someone else already
505	 * renewed this period, which is a success for us, not an error.
506	 */
507	async function commitRenewal(opts: {
508	  server: DueServer;
509	  charge: RenewalCharge;
510	  newExpiry: Date;
511	  /** Destination country the VAT was charged for (Finding 1); recorded on the invoice. */
512	  taxCountry?: string;
513	}): Promise<"renewed" | "insufficient" | "already"> {
514	  const { server, charge, newExpiry, taxCountry } = opts;
515	  const renewCents = charge.totalCents;
516	  const { netCents, taxCents, taxRatePercent, extraDiskCents, extraDiskMonthlyCents, backupCents, backupMonthlyCents } = charge;
517	  const periodStart = server.expiresAt!;
518	
519	  // `renewalCharge` bills `vpsTermPriceCents` (or a game plan's flat price) with NO
520	  // seasonal promo — renewals never get the intro discount, exactly as
521	  // lib/promotions.ts promises. So the months this renewal adds were sold at 0% off
522	  // and the term's stored rate basis must say so, or a later downgrade credits them
523	  // at a promo rate nobody was ever charged. Blended rather than overwritten for the
524	  // same reason as renewNow: this sweep only fires on already-expired servers (so
525	  // the blend is 0 in practice), but the shared helper means the two renewal paths
526	  // cannot express different rules for the same event.
527	  const renewedPercent = prorateBlendPercent({
528	    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
529	    currentMonths: remainingMonths(server.expiresAt, Date.now()),
530	    addedPercent: 0,
531	    addedMonths: charge.months,
532	  });
533	
534	  try {
535	    await db.$transaction(async (tx) => {
536	      const advanced = await tx.server.updateMany({
537	        where: { id: server.id, expiresAt: server.expiresAt },
538	        data: {
539	          expiresAt: newExpiry,
540	          termPromoPercent: renewedPercent,
541	          // The period is paid, so the collection state that belonged to it dies
542	          // with it. Leaving a stage behind would hand the NEXT period a
543	          // half-spent retry budget and the wrong dunning email.
544	          dunningStage: 0,
545	          dunningNextAt: null,
546	          dunningPayUrl: null,
547	        },
548	      });
549	      if (advanced.count === 0) throw new AlreadyRenewedError();
550	      await debitWallet(tx, server.userId, renewCents);
551	      await tx.walletTransaction.create({
552	        data: {
553	          userId: server.userId,
554	          amountCents: -renewCents,
555	          description: `Renewal: ${charge.label} (${server.hostname})`,
556	        },
557	      });
558	      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
559	      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
560	      // never producing a second invoice for the same period.
561	      await tx.invoice.create({
562	        data: invoiceCreateData({
563	          userId: server.userId,
564	          description: `Renewal: ${charge.label} (${server.hostname})`,
565	          status: "PAID",
566	          // Snapshot the card on file at charge time (null-safe for wallet-only users).
567	          paidBrand: server.user.cardBrand ?? null,
568	          paidLast4: server.user.cardLast4 ?? null,
569	          // VAT recorded separately; the line items below sum to the NET (netCents).
570	          taxCents,
571	          taxRatePercent,
572	          taxCountry: taxCountry ?? null,
573	          period: { start: periodStart, end: newExpiry },
574	          // Extra disk gets its OWN line so the customer sees exactly what the
575	          // permanent storage costs each cycle; the lines sum back to netCents.
576	          lineItems: [
577	            {
578	              description: `${charge.label} — ${server.hostname}`,
579	              qty: 1,
580	              unitCents: netCents - extraDiskCents - backupCents,
581	              amountCents: netCents - extraDiskCents - backupCents,
582	            },
583	            ...(extraDiskCents > 0
584	              ? [
585	                  {
586	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
587	                    qty: 1,
588	                    unitCents: extraDiskCents,
589	                    amountCents: extraDiskCents,
590	                  },
591	                ]
592	              : []),
593	            // Paid backup retention (Plus) gets its own line, mirroring extra disk,
594	            // so the customer sees exactly what the retention upsell costs each cycle.
595	            ...(backupCents > 0
596	              ? [
597	                  {
598	                    description: `Plus backups (keep 7) — ${server.hostname} ($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
599	                    qty: 1,
600	                    unitCents: backupCents,
601	                    amountCents: backupCents,
602	                  },
603	                ]
604	              : []),
605	          ],
606	        }),
607	      });
608	      await tx.auditLog.create({
609	        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
610	      });
611	      // First-month-free conversion: this is the server's SECOND term. Flip the
612	      // redemption anchored to it to renewed (idempotent, same tx as the money).
613	      await markPromoRenewed(tx, server.id);
614	    });
615	  } catch (e) {
616	    if (e instanceof InsufficientBalanceError) {
617	      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
618	      return "insufficient";
619	    }
620	    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
621	    throw e;
622	  }
623	
624	  // The period is settled. Any 3-D Secure challenge still hanging off it is a
625	  // loaded gun: anything that later confirms that intent takes a SECOND payment
626	  // for a period we have already been paid for. Only worth a Stripe round-trip
627	  // when this server was actually mid-dunning.
628	  if (server.dunningStage > 0 || server.dunningPayUrl) {
629	    await cancelPendingChargeForMarker(
630	      server.user.stripeCustomerId,
631	      renewalChargeMarker(server.id, periodStart),
632	    );
633	  }
634	  return "renewed";
635	}
