637	/**
638	 * Charge the saved card for the wallet shortfall, then renew.
639	 *
640	 * The card NEVER pays the invoice directly. It credits the wallet with exactly
641	 * what Stripe captured, and `commitRenewal` then debits the FULL renewal from the
642	 * wallet — identical to how checkout splits a purchase. That ordering is what
643	 * makes a crash safe in both directions: money captured but not yet applied sits
644	 * in the customer's wallet as credit (visible, spendable, refundable), and a
645	 * renewal can never be granted without a matching debit.
646	 *
647	 * TWO idempotency guards ride on every attempt:
648	 *  - `marker` (server + period) — a permanent pre-flight lookup at Stripe for a
649	 *    live PaymentIntent for this exact period, so a crash between "Stripe captured"
650	 *    and "we recorded it" replays instead of charging again.
651	 *  - `idempotencyKey` (server + period + attempt + amount) — Stripe replays an
652	 *    identical request for 24h, which covers two overlapping sweeps of the SAME
653	 *    scheduled attempt. The attempt and amount are in the key because a genuine
654	 *    day-3 retry, or a retry for a different remainder after the wallet moved, is a
655	 *    deliberately NEW charge; reusing the key there would make Stripe reject it.
656	 *
657	 * And the credit itself is guarded by the UNIQUE index on
658	 * `WalletTransaction.stripePaymentIntentId`, so even a replayed capture credits once.
659	 *
660	 * @returns true when the term was actually extended.
661	 */
662	async function attemptCardRenewal(opts: {
663	  server: DueServer;
664	  charge: RenewalCharge;
665	  cardCents: number;
666	  newExpiry: Date;
667	  now: Date;
668	  cfg: DunningConfig;
669	  /** Destination country the VAT was charged for; passed through to the invoice. */
670	  taxCountry?: string;
671	}): Promise<boolean> {
672	  const { server, charge, cardCents, newExpiry, now, cfg, taxCountry } = opts;
673	  const user = server.user;
674	  const periodStart = server.expiresAt!;
675	  const marker = renewalChargeMarker(server.id, periodStart);
676	  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
677	  const cardLabel = savedCardLabel(user) ?? "your saved card";
678	
679	  const result = await chargeSavedCardOffSession({
680	    user,
681	    amountCents: cardCents,
682	    description: `Renewal: ${charge.label} (${server.hostname})`,
683	    marker,
684	    idempotencyKey,
685	    metadata: {
686	      nxeonServerId: server.id,
687	      nxeonPeriodStart: periodStart.toISOString(),
688	      nxeonKind: "renewal",
689	    },
690	  });
691	
692	  if (result.ok) {
693	    // Exactly what Stripe took, not what we asked for — a replayed intent can carry
694	    // an older amount and the ledger must match the bank, not our intent.
695	    const credited = await creditOffSessionCharge({
696	      userId: server.userId,
697	      amountCents: result.amountCents,
698	      description: `Card payment for ${server.hostname} renewal (${cardLabel})`,
699	      paymentIntentId: result.paymentIntentId,
700	      // No invoice for the card leg: `commitRenewal` issues ONE paid invoice for
701	      // the whole renewal, and a second document for the card portion would
702	      // double-count the same revenue.
703	    });
704	    const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry });
705	
706	    // The receipt is tied to the CREDIT, not the renewal: `creditOffSessionCharge`
707	    // returns false on the P2002 that means "already credited", so a replayed
708	    // capture cannot email the same customer a second receipt for one charge.
709	    if (credited) {
710	      await mail(
711	        user.email,
712	        user.id,
713	        emails.paymentReceipt(
714	          fmtUsd(result.amountCents),
715	          `${charge.label} — ${server.hostname}`,
716	          user.cardLast4 ?? "",
717	        ),
718	        // ACCOUNT tier — a receipt is the one mail from this sweep a customer may
719	        // legitimately opt out of. Everything else here is CRITICAL by default.
720	        "receipt",
721	      );
722	    }
723	
724	    if (outcome === "insufficient") {
725	      // The card paid, the wallet was credited, and the debit STILL failed — the
726	      // customer spent the credit between our split read and the transaction. The
727	      // money is not lost, it is sitting in their wallet; re-run shortly rather
728	      // than charging again (the marker replays this same capture, so the next
729	      // pass cannot take a second payment) and do NOT count it as a dunning
730	      // failure, because nothing about their card went wrong.
731	      console.error(
732	        `[billing] ${server.hostname}: card captured ${fmtUsd(result.amountCents)} but the wallet debit fell short — retrying shortly`,
733	      );
734	      await rescheduleAttempt(server, new Date(now.getTime() + TRANSIENT_RETRY_MS));
735	      return false;
736	    }
737	    if (outcome === "renewed") {
738	      console.log(
739	        `[billing] renewed ${server.hostname} until ${newExpiry.toISOString()} (card ${fmtUsd(result.amountCents)}${result.replayed ? ", replayed" : ""})`,
740	      );
741	    }
742	    return true;
743	  }
744	
745	  if (result.kind === "transient") {
746	    // Our side or Stripe's side wobbled. Never a dunning event: a misclassified
747	    // transient costs a delayed renewal, a misclassified decline costs a paid-up
748	    // customer their server. The attempt counter is untouched.
749	    console.warn(`[billing] transient charge error for ${server.hostname}: ${result.message}`);
750	    await rescheduleAttempt(server, new Date(now.getTime() + TRANSIENT_RETRY_MS));
751	    return false;
752	  }
753	
754	  if (result.kind === "unavailable") {
755	    // `hasChargeableCard` already proved Stripe is configured and both ids are
756	    // present, and `walletSplit` keeps the amount above Stripe's floor — so the
757	    // only way here is `resource_missing`: the payment method no longer exists at
758	    // Stripe. Not a decline; there is nothing to retry until a new card is saved.
759	    // Clearing the columns matters twice over: the portal stops claiming a card is
760	    // on file, and `suspendDueAt` stops granting card-customer runway to an account
761	    // that has no card at all.
762	    console.warn(`[billing] saved card unusable for ${server.hostname}: ${result.message}`);
763	    await forgetMissingPaymentMethod(server.userId).catch((e) =>
764	      console.error("[billing] could not clear missing payment method", e),
765	    );
766	    // `server.user` is deliberately NOT mutated: this pass keeps the card-customer
767	    // runway and only the NEXT pass falls back to the shorter no-card grace. More
768	    // runway is always the safe direction for a fault the customer never saw coming.
769	    await rescheduleAttempt(server, null);
770	    await notify(
771	      server.userId,
772	      "Your saved card is no longer available",
773	      `We couldn't use the card saved for ${server.hostname} — your bank or Stripe no longer recognises it. Add a card to keep your services renewing automatically.`,
774	      "/dashboard/billing",
775	    );
776	    return false;
777	  }
778	
779	  if (result.kind === "requires_action") {
780	    // 3-D Secure. Off-session there is no browser to satisfy the challenge, so the
781	    // answer is a hosted Checkout link: the customer completes the bank step on
782	    // Stripe's own page, the money lands as wallet credit and the next sweep
783	    // renews from the wallet. This is NOT a decline — nothing about the card is
784	    // wrong — so it must never consume a retry, or a customer who simply hasn't
785	    // opened their email yet would be dunned toward suspension for their bank's
786	    // security policy.
787	    let payUrl = server.dunningPayUrl;
788	    if (!payUrl) {
789	      payUrl = await createOutstandingCheckout({
790	        user,
791	        amountCents: cardCents,
792	        hostname: server.hostname,
793	        serverId: server.id,
794	      });
795	      if (payUrl) {
796	        await db.server.update({ where: { id: server.id }, data: { dunningPayUrl: payUrl } });
797	        await mail(
798	          user.email,
799	          user.id,
800	          emails.paymentActionRequired(server.hostname, fmtUsd(cardCents), payUrl),
801	        );
802	        await notify(
803	          server.userId,
804	          `${server.hostname} — your bank needs to confirm the payment`,
805	          `Your card issuer asked for an extra verification step for ${fmtUsd(cardCents)}. Confirming it finishes the renewal. Nothing is suspended.`,
806	          `/dashboard/servers/${server.id}`,
807	        );
808	      }
809	    }
810	    // Re-check daily rather than hourly: the challenge does not move, and the same
811	    // link is already in their inbox. `dunningPayUrl` being set is what stops the
812	    // email repeating for this period; `clearStaleDunning`/`commitRenewal` clear it.
813	    server.dunningPayUrl = payUrl;
814	    await rescheduleAttempt(server, new Date(now.getTime() + MIN_RETRY_GAP_MS));
815	    console.log(`[billing] ${server.hostname} awaiting 3-D Secure confirmation for ${fmtUsd(cardCents)}`);
816	    return false;
817	  }
818	
819	  // Hard decline — the issuer said no. This is the only outcome that spends an
820	  // attempt and moves the customer along the dunning sequence.
821	  await recordDeclinedAttempt({ server, cardCents, now, cfg, reason: result.message });
822	  return false;
