825	/**
826	 * Book a real decline: advance `dunningStage`, schedule the next attempt from the
827	 * day-1/3/5 table and send the email that matches where the customer now is.
828	 *
829	 * The stage is CLAMPED at DUNNING_EXHAUSTED so a re-armed attempt (a new card
830	 * saved after the sequence ran out) that also fails cannot send a second final
831	 * notice or push the customer past the end of a schedule that has no more entries.
832	 */
833	async function recordDeclinedAttempt(opts: {
834	  server: DueServer;
835	  cardCents: number;
836	  now: Date;
837	  cfg: DunningConfig;
838	  reason: string;
839	}): Promise<void> {
840	  const { server, cardCents, now, cfg, reason } = opts;
841	  const prevStage = server.dunningStage;
842	  const newStage = Math.min(prevStage + 1, DUNNING_EXHAUSTED);
843	  const amount = fmtUsd(cardCents);
844	  const last4 = server.user.cardLast4 ?? "";
845	
846	  console.warn(`[billing] card declined for ${server.hostname} (attempt ${newStage}): ${reason}`);
847	
848	  const calendarSuspendAt = new Date(
849	    server.expiresAt!.getTime() + calendarSuspendDay(cfg, true) * DAY,
850	  );
851	
852	  if (prevStage >= DUNNING_EXHAUSTED) {
853	    // Already out of attempts; this was the extra try granted either by the stored
854	    // suspension time arriving or by `retryDunningNow` after the customer saved a
855	    // new card. Silent — they have already had the final notice, and a second copy
856	    // of it would be noise.
857	    //
858	    // The schedule drops back to the plain calendar deadline (already in the past by
859	    // now), so this attempt CANNOT defer the suspension it precedes. When the admin
860	    // kill switch is off nothing will ever be suspended, so fall back to a daily
861	    // cadence instead — otherwise a 10-minute sweep would attempt the same declining
862	    // card every 10 minutes forever, which is exactly how an issuer starts blocking
863	    // us outright.
864	    await rescheduleAttempt(
865	      server,
866	      cfg.autoSuspend ? calendarSuspendAt : new Date(now.getTime() + MIN_RETRY_GAP_MS),
867	    );
868	    return;
869	  }
870	
871	  // Where the customer is told to expect us next. While retries remain that is the
872	  // next attempt; once they are spent it is the ONE CLEAR DAY the final notice
873	  // promises — measured from this moment, not from expiry, so a sequence that ran
874	  // late (worker downtime) still gets its full day instead of being suspended in the
875	  // same pass that told the customer it was their last chance.
876	  const scheduledAt =
877	    nextRetryAt(server.expiresAt!, newStage, now) ??
878	    new Date(Math.max(calendarSuspendAt.getTime(), now.getTime() + DAY));
879	  // The date quoted in the email is derived from the state we are about to WRITE,
880	  // never from the row we read — `suspendDueAt` honours `dunningNextAt`, so quoting
881	  // the pre-update value would print a day earlier than the sweep actually acts on.
882	  const suspendAt =
883	    suspendDueAt(
884	      { expiresAt: server.expiresAt, dunningStage: newStage, dunningNextAt: scheduledAt },
885	      true,
886	      cfg,
887	    ) ?? calendarSuspendAt;
888	
889	  await db.server.update({
890	    where: { id: server.id },
891	    data: { dunningStage: newStage, dunningNextAt: scheduledAt },
892	  });
893	  server.dunningStage = newStage;
894	  server.dunningNextAt = scheduledAt;
895	
896	  await db.auditLog
897	    .create({
898	      data: {
899	        userId: server.userId,
900	        action: "billing.card_declined",
901	        detail: `${server.id}: attempt ${newStage} for ${amount} — ${reason.slice(0, 180)}`,
902	      },
903	    })
904	    .catch(() => {
905	      /* audit is bookkeeping; never let it break collection */
906	    });
907	
908	  if (newStage === 1) {
909	    // FIRST failure of the period. Five-positional-string overload — the object
910	    // form is the legacy catalog shape used by the admin template previewer.
911	    await mail(
912	      server.user.email,
913	      server.userId,
914	      emails.paymentFailed(server.hostname, amount, last4, fmtDay(scheduledAt), billingUrl()),
915	    );
916	  } else if (newStage < DUNNING_EXHAUSTED) {
917	    // `attempt` counts RETRIES (the expiry-day attempt is attempt 0), which is what
918	    // `emails.paymentRetryFailed` subtracts from DUNNING_RETRY_ATTEMPTS to tell the
919	    // customer how many tries are left.
920	    await mail(
921	      server.user.email,
922	      server.userId,
923	      emails.paymentRetryFailed(server.hostname, amount, newStage - 1, fmtDay(suspendAt), billingUrl()),
924	    );
925	  } else {
926	    await mail(
927	      server.user.email,
928	      server.userId,
929	      emails.paymentFinalNotice(server.hostname, amount, billingUrl()),
930	    );
931	  }
932	
933	  await notify(
934	    server.userId,
935	    `${server.hostname} — card payment ${newStage >= DUNNING_EXHAUSTED ? "failed, final notice" : "declined"}`,
936	    newStage >= DUNNING_EXHAUSTED
937	      ? `We've run out of automatic attempts for ${amount}. ${server.hostname} is still running — settle the balance to keep it that way.`
938	      : `We couldn't charge ${amount} to your card. Nothing is suspended; we'll try again on ${fmtDay(scheduledAt)}.`,
939	    `/dashboard/servers/${server.id}`,
940	  );
941	}
