943	/**
944	 * When the Nth failed attempt should be followed by another one.
945	 *
946	 * Floored at MIN_RETRY_GAP_MS so a worker that has been down for a week does not
947	 * discover four overdue slots at once and fire the entire sequence — three charges
948	 * and three emails — inside a single afternoon.
949	 */
950	function nextRetryAt(expiresAt: Date, failures: number, now: Date): Date | null {
951	  if (failures >= DUNNING_EXHAUSTED) return null;
952	  const scheduled = new Date(expiresAt.getTime() + retryDayFor(failures) * DAY);
953	  const floor = new Date(now.getTime() + MIN_RETRY_GAP_MS);
954	  return scheduled > floor ? scheduled : floor;
955	}
956	
957	/**
958	 * Move the next attempt WITHOUT spending a dunning attempt, keeping the in-memory
959	 * row in step with the write.
960	 *
961	 * The mirroring is load-bearing, not tidiness: `suspendDueAt` runs a few lines
962	 * later in the SAME pass and reads `dunningNextAt` to decide whether an attempt we
963	 * have promised is still outstanding. Reading the pre-update value there would
964	 * suspend a server seconds after we committed to trying its card again.
965	 */
966	async function rescheduleAttempt(server: DueServer, at: Date | null): Promise<void> {
967	  await db.server.update({ where: { id: server.id }, data: { dunningNextAt: at } });
968	  server.dunningNextAt = at;
969	}
