971	/* ------------------------------------------------------------------ *
972	 * Suspension
973	 * ------------------------------------------------------------------ */
974	
975	/**
976	 * When this overdue server may be paused — null means never (auto-suspend is off).
977	 *
978	 * With a card in play the deadline is CARD_SUSPEND_DAY past expiry: one clear day
979	 * after the final-notice email, so the customer always gets a full day with the
980	 * warning in hand before anything stops. Without a card there is nothing to wait
981	 * for beyond the configured grace period.
982	 *
983	 * The deadline also never lands BEFORE a date we have promised the customer. A
984	 * worker that was down for the first five days starts the sequence late, and
985	 * suspending on the calendar alone would then pause a server minutes after emailing
986	 * "we'll try your card again on <date>" or "this is your final notice" — the exact
987	 * broken promise this whole feature exists to stop. `dunningNextAt` carries that
988	 * promise (the next attempt while any remain, the clear day once they are spent),
989	 * and the slip it can buy is capped by SUSPEND_SLIP_CAP_DAYS so a permanently
990	 * failing Stripe cannot defer suspension forever.
991	 */
992	function suspendDueAt(
993	  server: { expiresAt: Date | null; dunningStage: number; dunningNextAt: Date | null },
994	  hasCard: boolean,
995	  cfg: DunningConfig,
996	): Date | null {
997	  if (!cfg.autoSuspend || !server.expiresAt) return null;
998	  const days = calendarSuspendDay(cfg, hasCard);
999	  const at = new Date(server.expiresAt.getTime() + days * DAY);
1000	  if (!hasCard || !server.dunningNextAt || server.dunningNextAt <= at) return at;
1001	  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
1002	  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
1003	}
1004	
1005	/**
1006	 * Days past expiry of the plain calendar deadline, before any late-sequence slip.
1007	 * One expression, because `suspendDueAt` and the exhausted-sequence bookkeeping in
1008	 * `recordDeclinedAttempt` must agree on it exactly or a server can be scheduled to
1009	 * pause on a day the suspension check does not recognise.
1010	 */
1011	function calendarSuspendDay(cfg: DunningConfig, hasCard: boolean): number {
1012	  return hasCard ? Math.max(cfg.graceDays, CARD_SUSPEND_DAY) : cfg.graceDays;
1013	}
1014	
1015	/**
1016	 * Pause an unpaid server: mark it, queue the SUSPEND job, tell the customer.
1017	 *
1018	 * `suspendReason: "UNPAID"` is load-bearing, not a label. It is what scopes
1019	 * `terminateOverdue` (below) and the auto-unsuspend in `renewNow` to billing
1020	 * suspensions only, so an abuse or admin suspension can never be deleted by the
1021	 * overdue sweep nor lifted by a customer paying a bill.
1022	 */
1023	async function suspendUnpaid(server: DueServer, cfg: DunningConfig): Promise<void> {
1024	  if (!cfg.autoSuspend) return; // admin kill switch — belt and braces
1025	  // Never queue a second SUSPEND behind one that is already queued or running:
1026	  // duplicate jobs against one VM are how a suspend/unsuspend race leaves a paid-up
1027	  // customer offline.
1028	  const pending = await db.job.count({
1029	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
1030	  });
1031	  if (pending !== 0) return;
1032	
1033	  await db.server.update({
1034	    where: { id: server.id },
1035	    data: {
1036	      suspendedNote: "unpaid — renew from your billing page to restore access",
1037	      // Only an UNPAID suspension may be terminated by the overdue sweep or
1038	      // lifted automatically by paying. See Server.suspendReason.
1039	      suspendReason: "UNPAID",
1040	    },
1041	  });
1042	  await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
1043	  await db.auditLog.create({
1044	    data: { userId: server.userId, action: "billing.suspended_unpaid", detail: server.id },
1045	  });
1046	  await db.notification.create({
1047	    data: {
1048	      userId: server.userId,
1049	      title: `${server.hostname} suspended — payment overdue`,
1050	      body: "Pay from the server page to restore access instantly.",
1051	      href: `/dashboard/servers/${server.id}`,
1052	    },
1053	  });
1054	  console.log(`[billing] suspending unpaid ${server.hostname}`);
1055	}
