1061	/**
1062	 * Warn before a saved card expires.
1063	 *
1064	 * A card that lapses turns a customer who has done nothing wrong into a dunning
1065	 * case: the renewal declines, the sequence starts, and the first they hear of it
1066	 * is "your card was declined". Thirty days' notice costs one email and prevents
1067	 * the whole sequence.
1068	 *
1069	 * `User.cardExpiryNotifiedAt` is both the sent-marker and the re-nudge clock, and
1070	 * `persistCard` (lib/stripe-cards.ts) resets it to null whenever a card is saved —
1071	 * so replacing an expiring card silently re-arms the warning for the new one
1072	 * instead of suppressing it forever.
1073	 */
1074	async function cardExpirySweep(now: Date): Promise<void> {
1075	  if (!stripeConfigured()) return;
1076	  const horizon = new Date(now.getTime() + CARD_EXPIRY_WARN_DAYS * DAY);
1077	  const renudgeBefore = new Date(now.getTime() - CARD_EXPIRY_RENUDGE_DAYS * DAY);
1078	
1079	  const users = await db.user.findMany({
1080	    where: {
1081	      suspended: false,
1082	      stripePaymentMethodId: { not: null },
1083	      cardExpMonth: { not: null },
1084	      cardExpYear: { not: null },
1085	      OR: [{ cardExpiryNotifiedAt: null }, { cardExpiryNotifiedAt: { lt: renudgeBefore } }],
1086	    },
1087	    select: {
1088	      id: true,
1089	      email: true,
1090	      cardBrand: true,
1091	      cardLast4: true,
1092	      cardExpMonth: true,
1093	      cardExpYear: true,
1094	    },
1095	  });
1096	
1097	  for (const user of users) {
1098	    // A card works THROUGH the last day of its expiry month; `cardExpiresAt`
1099	    // returns the first instant it stops working. Doing this arithmetic inline
1100	    // once got it off by a month, which either nags 30 days early or warns after
1101	    // the renewal has already declined.
1102	    const expiresAt = cardExpiresAt(user.cardExpMonth!, user.cardExpYear!);
1103	    if (expiresAt > horizon) continue;
1104	
1105	    await mail(
1106	      user.email,
1107	      user.id,
1108	      emails.cardExpiringSoon(user.cardLast4 ?? "", user.cardExpMonth!, user.cardExpYear!, billingUrl()),
1109	    );
1110	    // Written whether or not SMTP accepted it: a broken mail server must not turn
1111	    // this sweep into a mailer loop that retries the same address every 10 minutes.
1112	    await db.user.update({ where: { id: user.id }, data: { cardExpiryNotifiedAt: now } });
1113	    await notify(
1114	      user.id,
1115	      expiresAt <= now ? "Your saved card has expired" : "Your saved card expires soon",
1116	      `${savedCardLabel(user) ?? "The card on your account"} ${expiresAt <= now ? "can no longer be charged" : "expires soon"}. Save an up-to-date card so your renewals keep going through.`,
1117	      "/dashboard/billing",
1118	    );
1119	    console.log(`[billing] card-expiry notice sent to ${user.email}`);
1120	  }
1121	}
