1123	/**
1124	 * Honour the customer's own "keep my wallet topped up" preference.
1125	 *
1126	 * This is opt-in and customer-configured (`autoRechargeEnabled` /
1127	 * `autoRechargeThresholdCents` / `autoRechargeAmountCents`), and it is the only
1128	 * charge in this file that is NOT tied to a renewal — so unlike the renewal leg it
1129	 * DOES get its own invoice, because it is the whole payment rather than one part
1130	 * of a larger one.
1131	 *
1132	 * `autoRechargeMarker` is scoped to the account and the CALENDAR DAY, which caps
1133	 * this at one top-up per account per day no matter how many times the sweep runs
1134	 * or how fast the customer spends. Combined with the UNIQUE index on
1135	 * `WalletTransaction.stripePaymentIntentId`, a replayed capture credits once and
1136	 * emails once.
1137	 */
1138	async function autoRechargeSweep(now: Date): Promise<void> {
1139	  if (!stripeConfigured()) return;
1140	  const users = await db.user.findMany({
1141	    where: {
1142	      autoRechargeEnabled: true,
1143	      suspended: false,
1144	      stripeCustomerId: { not: null },
1145	      stripePaymentMethodId: { not: null },
1146	    },
1147	  });
1148	
1149	  for (const user of users) {
1150	    const threshold = user.autoRechargeThresholdCents ?? 0;
1151	    const amount = user.autoRechargeAmountCents ?? 0;
1152	    // A threshold of 0 means "never", and an amount below the floor the customer's
1153	    // own settings form enforces is a stale/hand-edited row — charging on either
1154	    // would be taking money the customer did not ask for.
1155	    if (threshold <= 0 || amount < AUTO_RECHARGE_MIN_CENTS) continue;
1156	    if (user.balanceCents >= threshold) continue;
1157	
1158	    const day = now.toISOString().slice(0, 10);
1159	    const marker = autoRechargeMarker(user.id, now);
1160	    let result: OffSessionResult;
1161	    try {
1162	      result = await chargeSavedCardOffSession({
1163	        user,
1164	        amountCents: amount,
1165	        description: `${AUTO_RECHARGE_DESC} — Nxeon wallet`,
1166	        marker,
1167	        idempotencyKey: `nxeon_autorecharge_${user.id}_${day}_${amount}`,
1168	        metadata: { nxeonKind: "auto_recharge" },
1169	      });
1170	    } catch (e) {
1171	      // One wedged account must not stop the others from topping up.
1172	      console.error(`[billing] auto-recharge error for ${user.email}`, e);
1173	      continue;
1174	    }
1175	
1176	    if (result.ok) {
1177	      const credited = await creditOffSessionCharge({
1178	        userId: user.id,
1179	        amountCents: result.amountCents,
1180	        description: `${AUTO_RECHARGE_DESC} (${savedCardLabel(user) ?? "saved card"})`,
1181	        paymentIntentId: result.paymentIntentId,
1182	        // This charge IS the whole payment, so it gets its own PAID invoice — in
1183	        // the same guarded write, so the invoice cannot outlive a rolled-back credit.
1184	        invoiceDescription: AUTO_RECHARGE_DESC,
1185	      });
1186	      if (!credited) continue; // already credited today — nothing new to announce
1187	      await mail(
1188	        user.email,
1189	        user.id,
1190	        emails.paymentReceipt(fmtUsd(result.amountCents), AUTO_RECHARGE_DESC, user.cardLast4 ?? ""),
1191	        "receipt", // ACCOUNT tier — suppressible; see the `mail()` default above.
1192	      );
1193	      await notify(
1194	        user.id,
1195	        `Wallet topped up ${fmtUsd(result.amountCents)}`,
1196	        `Your balance had dropped below ${fmtUsd(threshold)}, so we topped it up automatically using your saved card.`,
1197	        "/dashboard/billing",
1198	      );
1199	      console.log(`[billing] auto-recharged ${user.email} by ${fmtUsd(result.amountCents)}`);
1200	      continue;
1201	    }
1202	
1203	    if (result.kind === "unavailable") {
1204	      // The method is gone at Stripe. Clear it so the portal stops offering a card
1205	      // that cannot be charged (see the same branch in attemptCardRenewal).
1206	      await forgetMissingPaymentMethod(user.id).catch(() => {
1207	        /* best-effort */
1208	      });
1209	      continue;
1210	    }
1211	    if (result.kind !== "declined") continue; // transient / 3-D Secure: try again later, silently
1212	
1213	    // A declined top-up must NOT touch any server's dunning state — nothing is
1214	    // overdue, the customer simply asked us to keep a float. Tell them once a day
1215	    // and leave it there.
1216	    const already = await db.notification.findFirst({
1217	      where: {
1218	        userId: user.id,
1219	        title: { contains: "Automatic top-up" },
1220	        createdAt: { gt: new Date(now.getTime() - DAY) },
1221	      },
1222	    });
1223	    if (!already) {
1224	      await notify(
1225	        user.id,
1226	        "Automatic top-up declined",
1227	        `We couldn't charge ${fmtUsd(amount)} to your saved card for an automatic wallet top-up. Your services are unaffected — update your card when you get a moment.`,
1228	        "/dashboard/billing",
1229	      );
1230	    }
1231	  }
1232	}
