64	// Job types whose terminal failure genuinely leaves the VM in a bad/unknown
65	// run or disk state — only these should mark the server ERROR. Everything else
66	// (backup, snapshot-create, control-panel ops, SSL, migrate copy, game update…)
67	// is a side operation that doesn't touch the VM's run state.
68	//
69	// DISK_EXPAND is deliberately ABSENT: growing a disk never changes the VM's run
70	// state, so a failed expansion must leave the server RUNNING/STOPPED as it was.
71	// Its money is unwound by reconcileFailedJob instead.
72	const VM_STATE_FAILURE_JOBS = new Set<string>([
73	  "PROVISION", "REINSTALL", "DELETE", "RESIZE", "START", "STOP",
74	  "REBOOT", "SUSPEND", "UNSUSPEND", "BACKUP_RESTORE", "SNAPSHOT_ROLLBACK",
75	]);
