82	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any; user: any }> {
83	  const server = await db.server.findUnique({
84	    where: { id: job.serverId! },
85	    // `user` (email) + `node` (publicIp) are needed for the deployment
86	    // confirmation email fired on provision success; the rest is used throughout.
87	    include: { plan: true, osTemplate: true, node: true, user: { select: { id: true, email: true } } },
88	  });
89	  if (!server) throw new Error(`Server ${job.serverId} not found`);
90	  return server as any;
