93	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
94	async function nodeFor(server: any) {
95	  const n =
96	    server.node ??
97	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
98	    (await db.node.findFirst({ where: { enabled: true } }));
99	  if (!n) {
100	    // No Node rows yet — use the env-configured primary via the global client.
101	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
102	  }
103	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
104	}
