112	/**
113	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
114	 * plus any control-panel/app install script and selected add-ons. Long installs
115	 * run in the background so the VM reports ready promptly.
116	 */
117	function buildCloudInit(server: any): string {
118	  const addons = (server.addons ?? {}) as {
119	    malwareScanner?: boolean;
120	    dailyBackup?: boolean;
121	    docker?: boolean;
122	    claudeCode?: boolean;
123	  };
124	  const setup: string[] = [];
125	
126	  // Pre-bake Claude Code (Anthropic CLI) on every server unless explicitly opted
127	  // out. Customers SSH in and run `claude` using their own subscription or API
128	  // key — no setup on our side, zero token cost to us. Installs run in the
129	  // background (nohup below) so the VM still reports ready quickly.
130	  if (addons.claudeCode !== false) {
131	    // Same steps the backfill (task #73) runs on existing servers — one source of
132	    // truth in lib/claude-install.ts, so cloud-init and backfill never drift.
133	    setup.push(...CLAUDE_CLI_INSTALL_STEPS);
134	  }
135	
136	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
137	  if (addons.malwareScanner)
138	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
139	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
140	  // NxCloud: when this VM backs a managed Nextcloud instance, `provision` stashes
141	  // the per-instance install script here (admin creds injected). See worker/nxcloud.ts.
142	  if (server.__nxcloudSetup) setup.push(server.__nxcloudSetup);
143	
144	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
145	
146	  // Every VM gets a swapfile. A small plan (the 2 GB Starter is the common one)
147	  // with ZERO swap OOM-kills under any spike — a container image build, a traffic
148	  // burst, a migrated app's first request — and the kernel kills a process with no
149	  // warning and nothing to fall back on. A RAM-sized swapfile (capped so it never
150	  // eats a small root disk) turns a hard kill into slow-but-alive. Idempotent:
151	  // skips if any swap is already on or /swapfile already exists.
152	  const swapScript = [
153	    "#!/bin/bash",
154	    "# Nxeon: ensure a swapfile exists as an OOM safety net on small-RAM VMs.",
155	    "if swapon --show=NAME --noheadings 2>/dev/null | grep -q .; then exit 0; fi",
156	    "[ -e /swapfile ] && exit 0",
157	    'MEM_MB=$(awk "/MemTotal/{print int(\\$2/1024)}" /proc/meminfo 2>/dev/null || echo 1024)',
158	    "SWAP_MB=$MEM_MB",
159	    '[ "$SWAP_MB" -lt 1024 ] && SWAP_MB=1024',
160	    '[ "$SWAP_MB" -gt 4096 ] && SWAP_MB=4096',
161	    "# Leave >2 GB free on / so the swapfile never fills the root disk.",
162	    'AVAIL_MB=$(df -Pm / | awk "NR==2{print \\$4}")',
163	    '[ -n "$AVAIL_MB" ] && [ "$AVAIL_MB" -lt $((SWAP_MB + 2048)) ] && SWAP_MB=$((AVAIL_MB - 2048))',
164	    '[ "$SWAP_MB" -lt 256 ] && exit 0',
165	    "fallocate -l ${SWAP_MB}M /swapfile 2>/dev/null || dd if=/dev/zero of=/swapfile bs=1M count=${SWAP_MB} 2>/dev/null || exit 0",
166	    "chmod 600 /swapfile",
167	    "mkswap /swapfile >/dev/null 2>&1 || exit 0",
168	    "swapon /swapfile 2>/dev/null || exit 0",
169	    "grep -q '^/swapfile ' /etc/fstab 2>/dev/null || echo '/swapfile none swap sw 0 0' >> /etc/fstab",
170	    "grep -q '^vm.swappiness' /etc/sysctl.conf 2>/dev/null || { echo 'vm.swappiness=10' >> /etc/sysctl.conf; sysctl -w vm.swappiness=10 >/dev/null 2>&1 || true; }",
171	  ].join("\n");
172	
173	  // A friendly first-login guide + MOTD banner pointing at the portal hub.
174	  const welcome = [
175	    "# Welcome to your Nxeon server",
176	    "",
177	    "## Build anything with Claude Code — it's already installed",
178	    "",
179	    "1. You're already logged in. Just run:",
180	    "",
181	    "   claude",
182	    "",
183	    "2. Sign in once — either with your Claude subscription (Pro/Max) or an",
184	    "   Anthropic API key. See the step-by-step guide with screenshots at:",
185	    "",
186	    "   https://nxeon.cloud/dashboard/claude-code",
187	    "",
188	    "3. Then describe what you want in plain English, for example:",
189	    '   "Build a modern website for my coffee shop with a menu and contact form,',
190	    '    then run it and tell me the URL to preview it."',
191	    "",
192	    "Copy-paste starter prompts (spa site, booking app, REST API, Discord bot,",
193	    "and 20+ more) and how-to guides live in your portal at the link above.",
194	    "",
195	    "Happy building!",
196	  ].join("\n");
197	
198	  // Honest MOTD: check for the binary at login and only claim it's installed when
199	  // it really is. A failed background install must never greet the customer with
200	  // "Claude Code is pre-installed" and then 'command not found' — it tells them how
201	  // to install it instead.
202	  const motd = [
203	    "#!/bin/sh",
204	    'if [ -t 1 ]; then',
205	    '  if command -v claude >/dev/null 2>&1 || [ -x /usr/local/bin/claude ]; then',
206	    '    printf "\\n  \\033[1mNxeon\\033[0m — Claude Code is pre-installed on this server.\\n"',
207	    '    printf "  Run \\033[1mclaude\\033[0m to start building. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
208	    "  else",
209	    '    printf "\\n  \\033[1mNxeon\\033[0m — install Claude Code:  curl -fsSL https://claude.ai/install.sh | bash\\n"',
210	    '    printf "  Then run \\033[1mclaude\\033[0m. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
211	    "  fi",
212	    '  printf "  Full walkthrough: \\033[2m~/START-WITH-CLAUDE.md\\033[0m\\n\\n"',
213	    "fi",
214	  ].join("\n");
215	
216	  return `#cloud-config
217	package_update: true
218	packages:
219	  - qemu-guest-agent
220	ssh_pwauth: true
221	disable_root: false
222	write_files:
223	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
224	    permissions: "0644"
225	    content: |
226	      PermitRootLogin yes
227	      PasswordAuthentication yes
228	  - path: /root/START-WITH-CLAUDE.md
229	    permissions: "0644"
230	    content: |
231	${indentBlock(welcome, 6)}
232	  - path: /etc/profile.d/nxeon-welcome.sh
233	    permissions: "0755"
234	    content: |
235	${indentBlock(motd, 6)}
236	  - path: /root/nxeon-swap.sh
237	    permissions: "0755"
238	    content: |
239	${indentBlock(swapScript, 6)}
240	  - path: /root/nxeon-setup.sh
241	    permissions: "0755"
242	    content: |
243	${indentBlock(script, 6)}
244	runcmd:
245	  - systemctl enable --now qemu-guest-agent
246	  - systemctl restart ssh || systemctl restart sshd
247	  - /root/nxeon-swap.sh > /var/log/nxeon-swap.log 2>&1 || true
248	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
249	`;
250	}
