255	/**
256	 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
257	 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
258	 *
259	 * If the archive listing cannot be read we do NOT silently fall back to the raw
260	 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
261	 * and a provision that fails is recoverable while a cross-tenant disclosure is
262	 * not. The job retries; an operator sees why.
263	 */
264	async function allocateFreshVmid(conn: any): Promise<number> {
265	  const candidate = await conn.nextVmid();
266	  const archived = await archivedVmids(conn);
267	
268	  // Ids already in use, so skipping forward cannot land on a live VM. Read
269	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
270	  let taken = new Set<number>();
271	  try {
272	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
273	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
274	  } catch {
275	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
276	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
277	  }
278	
279	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
280	  if (skipped.length > 0) {
281	    console.warn(
282	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
283	        `from a previous server; allocated ${vmid} instead`
284	    );
285	  }
286	  return vmid;
287	}
