289	async function provision(job: Job) {
290	  const server = await loadServer(job);
291	  // Clear any stale failure reason from a previous attempt as this run starts, so
292	  // a successful retry doesn't leave the last error hanging around on the row.
293	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null } });
294	
295	  if (SANDBOX) {
296	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
297	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
298	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
299	    const password = generatePassword();
300	    const ip = sandboxIp(vmid);
301	    await db.server.update({
302	      where: { id: server.id },
303	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
304	    });
305	    await notify(
306	      server.userId,
307	      `Server ${server.hostname} is ready`,
308	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
309	      `/dashboard/servers/${server.id}`
310	    );
311	    // Post-purchase review request (once per server, skipped if no profiles set).
312	    await sendReviewRequestForServer(server.id);
313	    return;
314	  }
315	
316	  const { conn, row: nodeRow } = await nodeFor(server);
317	  const storage = server.plan.storageTier === "hdd"
318	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
319	    : nodeRow?.storageNvme ?? "vmdata";
320	
321	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
322	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
323	  // server's vzdump archives, so the id freed by a deletion comes back carrying
324	  // the old owner's backups — which every backup surface then attributes to the
325	  // new customer (listBackups/requestRestore key on vmid alone). See
326	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
327	  // keeps the vmid already persisted on the row.
328	  const vmid = server.vmid ?? (await allocateFreshVmid(conn));
329	  const password = generatePassword();
330	
331	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
332	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
333	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
334	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
335	  const { getSettingBool: _settingBool } = await import("../lib/settings");
336	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
337	  if (wantDedicated && ovhConfigured()) {
338	    try {
339	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
340	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
341	      dedicated = await allocateDedicatedIp(server.id, vmid);
342	    } catch (e) {
343	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
344	    }
345	  }
346	  // Node-aware + transactionally-claimed allocation (passing the server id enables
347	  // the claim path, so two concurrent provisions can't pick the same IP/port).
348	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
349	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
350	
351	  await db.server.update({
352	    where: { id: server.id },
353	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
354	  });
355	
356	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
357	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
358	  // (worker restart mid-clone, or any transient failure in the steps below) would
359	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
360	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
361	  // the clone is idempotent, so skip it when the VM is already present.
362	  let vmAlreadyExists = false;
363	  try {
364	    await conn.vmStatus(vmid);
365	    vmAlreadyExists = true;
366	  } catch {
367	    vmAlreadyExists = false;
368	  }
369	  if (vmAlreadyExists) {
370	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
371	  } else {
372	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
373	      newid: vmid,
374	      name: server.hostname,
375	      full: 1,
376	      storage,
377	    });
378	    await conn.waitForTask(cloneUpid, 600_000);
379	  }
380	
381	  // Per-server cloud-init snippet (base + panel/app install + add-ons).
382	  //
383	  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
384	  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
385	  // failed write hands the VM a vendor-data file that does not exist. Root SSH
386	  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
387	  // all silently vanish, and the customer is still told the server is ready.
388	  // Failing here is recoverable — the job retries, and the clone above is
389	  // idempotent. Continuing is not.
390	  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
391	  // generate its one-time admin password (persisted, once) and get the idempotent
392	  // install script to bake into cloud-init. Null for an ordinary VPS.
393	  (server as any).__nxcloudSetup = await nxcloudSetupForServer(server);
394	
395	  const snippet = buildCloudInit(server);
396	  try {
397	    await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8");
398	  } catch (e: any) {
399	    throw new Error(
400	      `could not write the cloud-init snippet ${SNIPPET_DIR}/nxeon-${vmid}.yaml (${e?.message ?? e}). ` +
401	        `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
402	        `stopped here rather than reporting a server that would not be usable.`
403	    );
404	  }
405	
406	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
407	  const sshkeys = keys.length
408	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
409	    : undefined;
410	  const cfg: Record<string, any> = {
411	    cores: server.plan.cpuCores,
412	    memory: server.plan.ramMB,
413	    ciuser: "root",
414	    cipassword: password,
415	    sshkeys,
416	    nameserver: "1.1.1.1 8.8.8.8",
417	    onboot: 1,
418	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
419	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
420	  };
421	  if (dedicated) {
422	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
423	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
424	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
425	  } else {
426	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
427	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
428	  }
429	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
430	
431	  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
432	  // customer bought as a deploy-time upsell, so the VM is born the right size and
433	  // no separate DISK_EXPAND job is needed on a fresh order.
434	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
435	    disk: "scsi0",
436	    size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
437	  });
438	
439	  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
440	  // for a NAT server. If it cannot be proved, the readiness message says so
441	  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
442	  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
443	  // its IP, which is a worse outcome than a missing forward.
444	  let natError: Error | null = null;
445	  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);
446	
447	  // Idempotent start. A worker restart (e.g. a deploy) can interrupt a provision
448	  // AFTER the VM was already created and started; the reaper then re-queues the job.
449	  // Starting an already-running VM makes Proxmox's start task fail with "already
450	  // running", which — before this guard — stranded a perfectly good, reachable VM in
451	  // ERROR forever (every retry hit the same wall). So skip the start when the VM is
452	  // already running, and treat an "already running" race as success rather than fatal.
453	  const alreadyRunning = await conn
454	    .vmStatus(vmid)
455	    .then((s: { status?: string } | null) => s?.status === "running")
456	    .catch(() => false);
457	  if (!alreadyRunning) {
458	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
459	    try {
460	      await conn.waitForTask(startUpid);
461	    } catch (e) {
462	      if (!/already running/i.test(String((e as { message?: unknown })?.message ?? ""))) throw e;
463	    }
464	  }
465	
466	  // `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
467	  // agent whether the machine actually booted before calling it ready (M7 #10).
468	  // A false here is reported, never downgraded into silence.
469	  const booted = SANDBOX ? true : await waitForGuestAgent(conn, conn.node, vmid);
470	
471	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
472	
473	  // Deployment confirmation email (transactional, deduped via EmailLog). Runs on
474	  // the provision money-path, so it is best-effort and must never fail the build.
475	  try {
476	    const { sendServerDeployedEmail } = await import("../lib/server-deployed-email");
477	    await sendServerDeployedEmail(server, (server as any).user);
478	  } catch (e) {
479	    console.error("[worker] deployment-confirmation email failed (non-fatal)", e);
480	  }
481	
482	  const isImage = server.osTemplate.category !== "PLAIN_OS";
483	  const sshLine = dedicated
484	    ? `ssh root@${dedicated.address}`
485	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
486	
487	  const caveats: string[] = [];
488	  if (natError) {
489	    caveats.push(
490	      `Port forwarding could NOT be confirmed for this server, so the SSH command above may not connect yet — ` +
491	        `we are not going to pretend otherwise. Support has been alerted (${natError.message.slice(0, 200)}).`
492	    );
493	  }
494	  if (!booted) {
495	    caveats.push(
496	      "The hypervisor started the VM, but its guest agent has not answered yet, so we cannot confirm the " +
497	        "operating system finished booting. Give it a few more minutes; if the SSH command still fails, open a ticket."
498	    );
499	  }
500	  const body = [
501	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
502	    ...caveats,
503	  ].join(" — ");
