533	/**
534	 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
535	 * lib/proxmox.ts for the incident and the ladder. The bare version of this
536	 * function threw on an already-absent VM, which is what made a retried REINSTALL
537	 * destroy a customer's server permanently.
538	 */
539	async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
540	  const host: VmDestroyHost = {
541	    probe: async (id) => {
542	      try {
543	        await conn.vmStatus(id);
544	        return "present";
545	      } catch (e) {
546	        // Only a vmid-anchored "config does not exist" proves absence. Anything
547	        // else (auth, network, a locked node) is genuinely unknown and must not
548	        // be read as "already gone".
549	        return isVmAbsentError(e, id) ? "absent" : "unknown";
550	      }
551	    },
552	    stop: async (id) => {
553	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
554	      await conn.waitForTask(stopUpid);
555	    },
556	    destroy: async (id) => {
557	      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
558	        "destroy-unreferenced-disks": 1,
559	        purge: 1,
560	      });
561	      await conn.waitForTask(delUpid, 600_000);
562	    },
563	  };
564	  return destroyVmIdempotent(host, vmid);
565	}
