567	async function remove(job: Job) {
568	  const server = await loadServer(job);
569	  const { conn } = await nodeFor(server);
570	  if (!SANDBOX && server.vmid) {
571	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
572	    // so the absent case no longer needs to be caught here at all. The catch that
573	    // remains is narrowed to this vmid: it used to swallow any error containing
574	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
575	    // `volume ... does not exist` — errors that mean the VM is very much still
576	    // running. On one of those the handler proceeded to delete the Server row and
577	    // every Volume row pinned to it, leaving a live VM with no database record:
578	    // invisible to billing, invisible to the panel, still holding the customer's
579	    // data and impossible to reach through any surface we own.
580	    try {
581	      await destroyVm(conn, server.vmid);
582	    } catch (e: any) {
583	      if (!isVmAbsentError(e, server.vmid)) throw e;
584	    }
585	    // Best-effort: remove the per-server cloud-init snippet
586	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
587	  }
588	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
589	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
590	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
591	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
592	  // diskName and keep billing forever. Remove them and notify the owner. (The
593	  // reinstall guard already blocks the accidental case; a full server delete is an
594	  // intentional teardown, so we drop the volumes with it.)
595	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
596	  if (orphanVolumes.length > 0) {
597	    await db.volume.deleteMany({ where: { serverId: server.id } });
598	    for (const v of orphanVolumes) {
599	      await notify(
600	        v.userId,
601	        `Volume "${v.name}" was removed`,
602	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
603	        "/dashboard/volumes",
604	      ).catch(() => {});
605	    }
606	  }
607	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
608	  // server.delete cascade removes THIS running Job row — the success-path
609	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
610	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
611	  await db.server.delete({ where: { id: server.id } });
612	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
613	  // DELETE, which then dies on "Server not found" and the sync is never retried
614	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
615	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
616	}
