618	async function reinstall(job: Job) {
619	  const server = await loadServer(job);
620	  if (SANDBOX) {
621	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
622	    await notify(
623	      server.userId,
624	      `Server ${server.hostname} reinstalled (sandbox)`,
625	      "The sandbox server was reinstalled (no real VM was touched).",
626	      `/dashboard/servers/${server.id}`
627	    );
628	    return;
629	  }
630	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
631	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
632	  // EVERY disk the vmid owns, including attached block-storage Volume disks
633	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
634	  // by that vmid, and both purge and the default destroy (which removes disks
635	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
636	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
637	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
638	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
639	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
640	  // can be re-attached after the reinstall. This runs BEFORE any status change or
641	  // destructive call, so a blocked reinstall touches nothing.
642	  //
643	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
644	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
645	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
646	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
647	  // let the worst path through: fill a volume, Detach (the UI says "Data is
648	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
649	  // Detaching is therefore NOT sufficient protection, and telling the customer to
650	  // detach was wrong advice; they must delete the volume (which destroys just
651	  // that disk, deliberately) or move it to another server first.
652	  const pinnedVolumes = await db.volume.findMany({
653	    where: { serverId: server.id },
654	  });
655	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
656	  const realPinned = pinnedVolumes.filter(
657	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
658	  );
659	  if (realPinned.length > 0) {
660	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
661	    throw new Error(
662	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
663	        `Reinstalling purges every disk this server owns — including detached volumes ` +
664	        `that are still assigned to it — and that cannot be undone.`
665	    );
666	  }
667	
668	  const { conn } = await nodeFor(server);
669	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
670	  if (server.vmid) await destroyVm(conn, server.vmid);
671	  await provision(job);
672	}
