674	async function suspend(job: Job, unsuspend: boolean) {
675	  const server = await loadServer(job);
676	  if (SANDBOX) {
677	    if (unsuspend) {
678	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
679	    } else {
680	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
681	    }
682	    return;
683	  }
684	  const { conn, row: nodeRow } = await nodeFor(server);
685	  if (unsuspend) {
686	    // The dedicated IP was returned to the pool while suspended — re-allocate one
687	    // and reconfigure the public network before starting the VM back up.
688	    if (server.vmid) {
689	      const { getSettingBool: _sb } = await import("../lib/settings");
690	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
691	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
692	      let reconfigured = alreadyHas ? true : false;
693	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
694	        try {
695	          const d = await allocateDedicatedIp(server.id, server.vmid);
696	          if (d) {
697	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
698	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
699	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
700	            });
701	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
702	            reconfigured = true;
703	          }
704	        } catch (e) {
705	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
706	        }
707	      }
708	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
709	      // the Virtual MAC + failover IP that suspend released back to the pool — that
710	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
711	      // with a valid, non-conflicting network instead of a dead public config.
712	      if (!reconfigured) {
713	        try {
714	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
715	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
716	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
717	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
718	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
719	          });
720	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
721	        } catch (e) {
722	          console.error("[worker] NAT fallback on unsuspend failed", e);
723	        }
724	      }
725	    }
726	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null, suspendReason: null } });
727	    // Not fatal to the unsuspend itself (the customer is paid up and the VM must
728	    // come back), but never silent: an unproved sync is logged with its reason.
729	    if (!SANDBOX) await syncPortForwardsBestEffort(`unsuspend ${server.hostname}`);
730	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
731	    await conn.waitForTask(upid);
732	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
733	  } else {
734	    try {
735	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
736	      await conn.waitForTask(upid);
737	    } catch { /* may already be stopped */ }
738	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
739	    if (!SANDBOX) await syncPortForwardsBestEffort(`suspend ${server.hostname}`);
740	    // Return the dedicated IP to the pool while the server is suspended, so it
741	    // can be handed to a paying server. Re-allocated on unsuspend.
742	    if (ovhConfigured()) {
743	      try {
744	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
745	        if (had) {
746	          await releaseDedicatedIp(server.id);
747	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
748	          // so leaving the released IP here makes the next server that claims it fail
749	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
750	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
751	          await db.server.update({
752	            where: { id: server.id },
753	            data: { ipAddress: null, ipv6: null },
754	          });
755	        }
756	      } catch (e) {
757	        console.error("[worker] release dedicated IP on suspend failed", e);
758	      }
759	    }
760	  }
761	}
