779	 * `error` is the redacted Job.error; we keep a trimmed copy for the customer.
780	 */
781	async function notifyProvisionFailed(
782	  server: { id: string; userId: string; hostname: string },
783	  error: string,
784	): Promise<void> {
785	  // A concise, customer-facing reason. The raw Job.error can be a 2000-char stack;
786	  // the first line is almost always the meaningful message.
787	  const reason = (error.split("\n")[0] || error).trim().slice(0, 300);
788	  try {
789	    await db.server.update({ where: { id: server.id }, data: { provisionError: reason } });
790	  } catch (e) {
791	    console.error("[worker] persist provisionError failed", e);
792	  }
793	  // If this VM backs a managed NxCloud, mark the wrapper FAILED too — otherwise a
794	  // failed nxcloud provision leaves the instance stuck on "setting up" forever
795	  // while the backing Server sits in ERROR. Its dashboard card reads this to show
796	  // the failed/retry state (components/customer/NxcloudClient.tsx).
797	  try {
798	    await db.nxCloudInstance.updateMany({
799	      where: { serverId: server.id, status: { notIn: ["DELETING", "ACTIVE"] } },
800	      data: { status: "FAILED", error: reason },
801	    });
802	  } catch (e) {
803	    console.error("[worker] mark nxcloud instance failed", e);
804	  }
805	  await notify(
806	    server.userId,
807	    `We couldn't set up ${server.hostname}`,
808	    `Provisioning failed and our team has been notified. You can retry it or contact support from the server page.`,
809	    `/dashboard/servers/${server.id}`,
810	  );
811	  try {
812	    const { sendMail, emails } = await import("../lib/mailer");
813	    const user = await db.user.findUnique({ where: { id: server.userId }, select: { email: true } });
814	    if (user?.email) {
815	      const tpl = emails.provisionFailed({ hostname: server.hostname, reason });
816	      await sendMail({
817	        to: user.email,
818	        subject: tpl.subject,
819	        html: tpl.html,
820	        template: tpl.template,
821	        userId: server.userId,
822	        // No `kind` → always send. A paid-for server that failed to build is a
823	        // service-delivery failure the customer must hear about.
824	      });
825	    }
826	  } catch (e) {
827	    console.error("[worker] provision-failure email failed", e);
828	  }
829	}
