831	async function resize(job: Job) {
832	  const server = await loadServer(job);
833	  const payload = (job.payload ?? {}) as { planId?: string };
834	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
835	  if (!newPlan) throw new Error("resize: target plan not found");
836	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
837	
838	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
839	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
840	  // never written here. Sizes below are therefore always the EFFECTIVE size
841	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
842	  // disk of any server carrying extra storage, and the resize would hard-fail.
843	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
844	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
845	  const diskLine =
846	    server.extraDiskGB > 0
847	      ? `${newTotalDiskGB} GB disk (${newPlan.diskGB} GB plan + ${server.extraDiskGB} GB added storage)`
848	      : `${newPlan.diskGB} GB disk`;
849	
850	  if (SANDBOX) {
851	    await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
852	    await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
853	      `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
854	      `/dashboard/servers/${server.id}`);
855	    return;
856	  }
857	
858	  const { conn } = await nodeFor(server);
859	  const wasRunning = server.status === "RUNNING";
860	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
861	    cores: newPlan.cpuCores,
862	    memory: newPlan.ramMB,
863	  });
864	  if (newTotalDiskGB > currentTotalDiskGB) {
865	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
866	      disk: "scsi0",
867	      size: `${newTotalDiskGB}G`,
868	    });
869	  }
870	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
871	  // CPU/RAM changes need a power cycle to apply
872	  if (wasRunning) {
873	    try {
874	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
875	      await conn.waitForTask(stopUpid, 120_000);
876	    } catch {
877	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
878	      await conn.waitForTask(stopUpid);
879	    }
880	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
881	    await conn.waitForTask(startUpid);
882	  }
883	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
884	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
885	    `/dashboard/servers/${server.id}`);
886	}
