1001	 * Create one backup and PROVE it exists before saying so.
1002	 *
1003	 * INCIDENT H4 (2026-07-26 rehearsal): this handler gated only the vzdump task's
1004	 * exit status — it never checked that an archive was written, had no failure
1005	 * notification, and `Server.lastAutoBackup` was stamped by the SWEEP at enqueue
1006	 * time. A customer could read "Last automatic backup: today" every night for a
1007	 * month with nothing in storage, and find out at restore time.
1008	 *
1009	 * Now: snapshot the archive list before the run, re-read it after, and require a
1010	 * volid that was not there and is not empty (`freshBackupProof`). Only that
1011	 * writes `lastAutoBackup`. A failure notifies the customer with the reason and a
1012	 * command, rather than leaving a stale-but-cheerful timestamp behind.
1013	 */
1014	async function backupCreate(job: Job) {
1015	  const server = await loadServer(job);
1016	  if (SANDBOX) {
1017	    await sandboxAnimateJob(job.id, [
1018	      { pct: 5, step: "Starting" },
1019	      { pct: 25, step: "Creating archive… 25%" },
1020	      { pct: 55, step: "Creating archive… 55%" },
1021	      { pct: 80, step: "Creating archive… 80%" },
1022	      { pct: 95, step: "Finalizing" },
1023	      { pct: 100, step: "Backup complete" },
1024	    ]);
