1026	    // column means "a backup was observed in storage".
1027	    await notify(
1028	      server.userId,
1029	      `Backup simulated (sandbox) for ${server.hostname}`,
1030	      "Sandbox only — no VM was contacted and no archive was written. This is not a restore point.",
1031	      `/dashboard/servers/${server.id}`
1032	    );
1033	    return;
1034	  }
1035	  if (server.vmid == null) {
1036	    throw new Error("backup: this server has no VMID yet, so there is nothing to back up.");
1037	  }
1038	  const vmid = server.vmid;
1039	
1040	  try {
1041	    await reportJobProgress(job.id, 2, "Starting");
1042	    const { conn } = await nodeFor(server);
1043	
1044	    // Snapshot what already exists. Membership of this set — not a timestamp
1045	    // comparison — is what makes "a new archive appeared" unarguable: ctime comes
1046	    // off the hypervisor and our window would come off the worker's clock.
1047	    const before = await listBackupsOn(conn, vmid);
1048	
1049	    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
1050	      vmid,
1051	      storage: "backup",
1052	      mode: "snapshot",
1053	      compress: "zstd",
1054	    });
1055	    await waitForTaskProgress(
1056	      conn,
1057	      upid,
1058	      (progress, step) => reportJobProgress(job.id, progress, step),
1059	      { timeoutMs: 3_600_000, phase: "backup" }
1060	    );
1061	
1062	    await reportJobProgress(job.id, 96, "Verifying archive");
1063	    const after = await listBackupsOn(conn, vmid);
1064	    const proof = freshBackupProof({ vmid, before, after });
1065	    if (!proof.proven) throw new Error(`backup not verified — ${proof.reason}`);
1066	
1067	    await reportJobProgress(job.id, 100, "Backup complete");
1068	
1069	    // Retention: keep the latest N backups for this server (N = the paid backup
1070	    // tier's keep count, an explicit backupKeep override winning); prune the rest.
1071	    const keep = resolveBackupKeep(server.backupTier, server.backupKeep);
1072	    try {
1073	      const pruned = await pruneBackups(conn, vmid, keep);
1074	      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${vmid} (keep ${keep})`);
