1076	      console.error(`[backup] prune failed for vmid ${vmid}`, e);
1077	    }
1078	
1079	    // The ONLY writer of lastAutoBackup, and only on proof.
1080	    await db.server.update({ where: { id: server.id }, data: { lastAutoBackup: new Date() } });
1081	
1082	    await notify(
1083	      server.userId,
1084	      `Backup completed for ${server.hostname}`,
1085	      `Verified present in backup storage: ${proof.volid} (${humanBytes(proof.sizeBytes)}).`,
1086	      `/dashboard/servers/${server.id}`
1087	    );
1088	  } catch (e: any) {
1089	    // Tell the customer it broke. Only on the final attempt, so the worker's
1090	    // three retries do not produce three notifications for one bad night.
1091	    if (job.attempts >= MAX_ATTEMPTS) {
1092	      await notify(
1093	        server.userId,
1094	        `Backup FAILED for ${server.hostname}`,
1095	        `${String(e?.message ?? e).slice(0, 400)} — this server has no new restore point. ` +
1096	          `Your last verified backup (if any) is shown under Backups.`,
1097	        `/dashboard/servers/${server.id}`
1098	      );
1099	    }
1100	    throw e;
1101	  }
1102	}
