/**
 * Record the card off a completed `mode: "payment"` Checkout session.
 *
 * The twin of `saveCardFromSetupSession`, for the three "customer pays" sessions
 * (VPS order, game order, wallet top-up) that now carry
 * `payment_intent_data.setup_future_usage = "off_session"`. Stripe attaches the
 * payment method to the customer as part of that capture; this reads it back off
 * the PaymentIntent, makes it the customer's default and mirrors it onto the
 * account so the billing sweep can auto-charge renewals.
 *
 * Takes the ALREADY-RETRIEVED session (fulfil-checkout has it) rather than an id,
 * so the one session read is shared. The session from `retrieveCheckoutSession`
 * is unexpanded, so `payment_intent` is an id string — we retrieve the intent with
 * the payment method expanded.
 *
 * NEVER throws and NEVER writes anything but the card mirror: the money has
 * already moved and been fulfilled by the time this runs, so a failure here must
 * be inert. Returns `{ card }` on success or `{ error }` otherwise.
 */
export async function saveCardFromPaymentSession(
  session: Stripe.Checkout.Session,
  userId: string,
): Promise<{ card?: SavedCard; error?: string }> {
  if (!stripeConfigured()) return { error: "Card payments are not configured." };
  try {
    const piRef = session.payment_intent;
    const piId = typeof piRef === "string" ? piRef : (piRef?.id ?? null);
    const customerId =
      typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
    if (!piId || !customerId) return { error: "No payment intent / customer on the session." };

    const pi = await stripe().paymentIntents.retrieve(piId, { expand: ["payment_method"] });
    const pmRef = pi.payment_method;
    const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
    if (!pmId) return { error: "No payment method on the payment intent." };
    // Expanded above, so usually already the object; fall back to a retrieve.
    const pm: Stripe.PaymentMethod =
      pmRef && typeof pmRef !== "string" ? pmRef : await stripe().paymentMethods.retrieve(pmId);

    // Make it the customer's default — best-effort, exactly like the setup version;
    // our own `stripePaymentMethodId` is the source of truth for charging.
    await stripe()
      .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
      .catch(() => {
        /* non-fatal */
      });
    await persistCard(userId, customerId, pm);
    return {
      card: {
        brand: pm.card?.brand ?? null,
        last4: pm.card?.last4 ?? null,
        expMonth: pm.card?.exp_month ?? null,
        expYear: pm.card?.exp_year ?? null,
      },
    };
  } catch (e) {
    console.error("[cards] could not record card from payment session", e);
    return { error: "We couldn't record the card from this payment." };
  }
}

