type ReminderServerRow = DueServer & { renewalReminderSentAt: Date | null };
type ReminderServerDelegate = {
  findMany(args: {
    where?: Record<string, unknown>;
    include?: Record<string, unknown>;
    take?: number;
    orderBy?: Record<string, "asc" | "desc">;
  }): Promise<ReminderServerRow[]>;
  update(args: { where: { id: string }; data: Record<string, unknown> }): Promise<unknown>;
};
function reminderServer(): ReminderServerDelegate {
  return db.server as unknown as ReminderServerDelegate;
}

/** Read `renewalReminderSentAt` off an in-memory row through the same shim. */
function reminderSentAt(server: { id: string }): Date | null {
  return (server as unknown as { renewalReminderSentAt?: Date | null }).renewalReminderSentAt ?? null;
}

/** Most reminder emails to send in a single sweep. */
const RENEWAL_REMINDER_CAP = 200;

/**
 * Nudge card-less customers BEFORE their renewal fails.
 *
 * A customer with no saved card whose wallet cannot cover the upcoming renewal is
 * heading straight for the dunning sequence: the sweep tries to charge a card that
 * isn't there, the renewal can't complete, and the first they hear of it is a
 * failure notice. One reminder — "add a card so the renewal goes through" — a few
 * days ahead costs one email and skips the whole sequence.
 *
 * Fires at most once per renewal cycle: `renewalReminderSentAt` is the sent-marker
 * and `commitRenewal` resets it to null when the period actually renews, so the
 * NEXT approach-to-expiry can remind again. Best-effort per server (one failure
 * never aborts the batch) and capped per run.
 */
export async function renewalReminderSweep(now = new Date()): Promise<void> {
  const days = Math.max(1, await getSettingInt("renewal_reminder_days", 3));
  const soon = new Date(now.getTime() + days * DAY);
  const candidates = await reminderServer().findMany({
    where: {
      isFree: false,
      autoRenew: true,
      status: { in: ["RUNNING", "STOPPED"] },
      // Approaching expiry but NOT yet expired — an already-expired server is the
      // renewal sweep's job (dunning/suspend), not this courtesy reminder's.
      expiresAt: { gt: now, lt: soon },
      // Not yet reminded this cycle. Reset to null by `commitRenewal` on renewal.
      renewalReminderSentAt: null,
    },
    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
    take: RENEWAL_REMINDER_CAP,
  });
  if (candidates.length === 0) return;

  const prices = {
    ipMonthlyCents: await dedicatedIpMonthlyCents(),
    extraDiskPerGbCents: await extraDiskPerGbCents(),
    backupPlusCents: await backupPlusMonthlyCents(),
    annualDiscountPct: await annualDiscountPct(),
  };
  const taxParams = { sellerCountry: await sellerCountry(), fallbackPercent: await taxRate() };

  for (const server of candidates) {
    try {
      // Only remind when BOTH escape hatches are shut: no chargeable card AND the
      // wallet can't cover the renewal. Either one on its own means the renewal
      // succeeds untouched, and a reminder would raise a false alarm.
      if (hasChargeableCard(server.user)) continue;
      const taxCtx = resolveCountryTaxRate({
        country: server.user.billingCountry ?? null,
        vatId: server.user.vatId ?? null,
        sellerCountry: taxParams.sellerCountry,
        fallbackPercent: taxParams.fallbackPercent,
      });
      const renewCents = renewalCharge(server, { ...prices, taxRatePercent: taxCtx.ratePercent }).totalCents;
      if (server.user.balanceCents >= renewCents) continue;

      await mail(
        server.user.email,
        server.userId,
        emails.renewalNeedsCard({
          hostname: server.hostname,
          date: fmtDay(server.expiresAt!),
          addCardUrl: billingUrl(),
        }),
        // ACCOUNT tier — a courtesy reminder the customer may opt out of by email.
        // The CRITICAL dunning sequence still fires if the renewal actually fails.
        "receipt",
      );
      await reminderServer().update({
        where: { id: server.id },
        data: { renewalReminderSentAt: now },
      });
      console.log(`[billing] renewal reminder (no card on file) sent for ${server.hostname}`);
    } catch (e) {
      console.error(`[billing] renewal reminder failed for ${server.hostname}`, e);
    }
  }
}

