// Pre-renewal "no card on file" reminder — hourly is plenty for a once-per-cycle
// nudge a few days ahead of expiry. Separate cadence from the 10-minute renewal
// sweep so it stays cheap (one indexed query) and its own failure is isolated.
if (Date.now() - lastRenewalReminderSweep > 60 * 60_000) {
  lastRenewalReminderSweep = Date.now();
  try {
    await renewalReminderSweep();
  } catch (e) {
    console.error("[billing] renewal-reminder sweep error", e);
  }
}

